insert into public.recipes as saved
  (id, name, category, difficulty, prep_time, bake_time, servings, pan, rating, diet, ingredients, instructions, source, tested, owner)
values
  (1, 'Thick, Chewy Oatmeal Raisin Cookies', 'cookies', 'easy', 15, 11, 24, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":115,"unit":"g"},{"name":"light brown sugar","amount":125,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":95,"unit":"g"},{"name":"baking soda","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":1.5,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"rolled oats","amount":120,"unit":"g"},{"name":"raisins","amount":120,"unit":"g"},{"name":"walnuts, chopped (optional)","amount":65,"unit":"g"}]'::jsonb, array['Beat the soft butter, brown sugar, egg and vanilla until smooth.', 'Whisk the flour, baking soda, cinnamon and salt in another bowl, then stir them into the butter mixture.', 'Stir in the oats, raisins and walnuts.', 'Chill the dough until firm, about 30 minutes. Cold dough bakes into thicker cookies.', 'Heat the oven to 175°C and line a tray with parchment.', 'Scoop the dough onto the tray 5 cm apart and bake 10 to 12 minutes, until the edges are golden and the tops still look slightly underdone.', 'Leave on the tray for 5 minutes, then cool on a rack.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2009/02/thick-chewy-oatmeal-raisin-cookies/"}'::jsonb, false, null),
  (2, 'Buttery Snickerdoodles', 'cookies', 'easy', 15, 9, 48, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":149,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":160,"unit":"g"},{"name":"sugar for rolling","amount":25,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line two trays.', 'Beat the soft butter and sugar until smooth, then beat in the egg.', 'Mix in the vanilla, salt and baking powder, then the flour, until no dry patches remain.', 'Shake the rolling sugar and cinnamon together in a bag or bowl.', 'Roll the dough into 2.5 cm balls and coat them in the cinnamon sugar.', 'Place 4 cm apart and flatten each to about 1 cm.', 'Bake 8 minutes for soft cookies or 10 for crisp ones. Cool on the tray, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/buttery-snickerdoodles-recipe"}'::jsonb, false, null),
  (3, 'Salted Chocolate Chunk Cookies', 'cookies', 'easy', 20, 12, 20, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"turbinado sugar","amount":25,"unit":"g"},{"name":"light brown sugar","amount":165,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"baking soda","amount":4.5,"unit":"g"},{"name":"salt","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":220,"unit":"g"},{"name":"bittersweet chocolate, chopped","amount":225,"unit":"g"},{"name":"flaky sea salt, for the top","amount":2,"unit":"g"}]'::jsonb, array['Heat the oven to 180°C and line a tray with parchment.', 'Beat the soft butter with all three sugars for about 5 minutes, until very pale and fluffy.', 'Beat in the egg and vanilla, scraping the bowl, then the baking soda and salt.', 'Mix in the flour on low speed until just combined. The dough looks crumbly.', 'Fold in the chopped chocolate.', 'Scoop mounds of about a tablespoon and a half, spaced well apart, and sprinkle each with a little flaky salt.', 'Bake 11 to 12 minutes, until golden outside and still soft in the middle. Rest 5 minutes on the tray, then move to a rack.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2015/04/salted-chocolate-chunk-cookies/"}'::jsonb, false, null),
  (4, 'Classic Shortbread', 'cookies', 'easy', 15, 38, 16, 'round-23', null, array['vegetarian']::text[], '[{"name":"salted butter","amount":227,"unit":"g"},{"name":"icing sugar","amount":113,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C. Grease a 23 cm round tin and line it with parchment.', 'Beat the butter, icing sugar, vanilla and salt until smooth.', 'Add the flour and mix until a stiff dough forms. If it will not come together, add a spoonful of water.', 'Press the dough evenly into the tin and prick it all over with a fork.', 'Bake 35 to 40 minutes until pale gold on top and deeper gold at the edges.', 'Cool 5 to 10 minutes in the tin, then turn out and cut into wedges while still warm.', 'Cool the pieces on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/shortbread-recipe"}'::jsonb, false, null),
  (5, 'Anzac Biscuits', 'cookies', 'easy', 15, 15, 18, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"rolled oats","amount":90,"unit":"g"},{"name":"unsweetened desiccated coconut","amount":85,"unit":"g"},{"name":"sugar","amount":165,"unit":"g"},{"name":"butter","amount":150,"unit":"g"},{"name":"golden syrup","amount":85,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"}]'::jsonb, array['Heat the oven to 180°C and line two trays with parchment.', 'Mix the flour, oats, coconut and sugar in a bowl.', 'Melt the butter and golden syrup in a pan over medium-high heat, stirring.', 'Stir in the baking soda. It will fizz up: take the pan off the heat straight away.', 'Pour the butter mixture into the dry ingredients and mix until just combined. It is crumbly but holds when pressed.', 'Squeeze tablespoons of the mixture into balls, flatten them into patties and space 2.5 cm apart on the trays.', 'Bake 15 minutes, swapping the trays halfway, until deep golden (12 minutes for chewy biscuits).', 'Leave on the trays for 5 minutes, then cool on a rack. They harden as they cool.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/anzac-biscuits-golden-oatmeal-cookies/"}'::jsonb, false, null),
  (6, 'Gingerbread Cookies', 'cookies', 'medium', 35, 9, 36, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":170,"unit":"g"},{"name":"brown sugar","amount":159,"unit":"g"},{"name":"molasses","amount":255,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"ground ginger","amount":4,"unit":"g"},{"name":"ground cloves","amount":1,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":450,"unit":"g"}]'::jsonb, array['Melt the butter and stir in the brown sugar, molasses, salt and spices.', 'Let it cool until lukewarm, then beat in the egg.', 'Whisk the baking powder and soda into the flour and stir it in. The dough will be soft and sticky: do not add extra flour.', 'Halve the dough, flatten each half into a thick rectangle, wrap and chill at least 1 hour.', 'Heat the oven to 175°C and line trays.', 'Roll the dough 3 to 6 mm thick and cut shapes, close together to waste less.', 'Bake 8 to 10 minutes until the edges darken slightly.', 'Cool on the trays, then on a rack, and decorate if you like.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/gingerbread-cookies-recipe"}'::jsonb, false, null),
  (7, 'The Chewy Chocolate Chip Cookies', 'cookies', 'medium', 20, 15, 24, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":227,"unit":"g"},{"name":"bread flour","amount":340,"unit":"g"},{"name":"kosher salt","amount":4,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"sugar","amount":57,"unit":"g"},{"name":"light brown sugar","amount":227,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"whole milk","amount":28,"unit":"g"},{"name":"vanilla extract","amount":6,"unit":"g"},{"name":"semisweet chocolate chips","amount":340,"unit":"g"}]'::jsonb, array['Melt the butter over low heat and let it cool slightly.', 'Sift the bread flour, salt and baking soda together.', 'Pour the butter into a mixer bowl, add both sugars and beat on medium for 2 minutes.', 'Whisk the egg, yolk, milk and vanilla together. Add slowly to the butter mixture on low speed and mix about 30 seconds.', 'Add the flour mixture a little at a time, scraping the bowl. Once it is mixed in, stir in the chocolate chips.', 'Chill the dough for 1 hour.', 'Heat the oven to 190°C with racks in the upper and lower thirds. Scoop 45 g portions onto parchment-lined trays, 6 to a tray.', 'Bake two trays at a time for 15 minutes, swapping them halfway. Slide the parchment onto a rack and cool at least 5 minutes.']::text[], '{"name":"Food Network","url":"https://www.foodnetwork.com/recipes/alton-brown/the-chewy-recipe-1909046"}'::jsonb, false, null),
  (8, 'Roll-Out Sugar Cookies', 'cookies', 'medium', 25, 8, 36, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":375,"unit":"g"},{"name":"baking powder","amount":3,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"butter","amount":227,"unit":"g"},{"name":"sugar","amount":200,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"milk","amount":15,"unit":"g"},{"name":"icing sugar, for rolling","amount":30,"unit":"g"}]'::jsonb, array['Sift the flour, baking powder and salt together.', 'Beat the soft butter and sugar until pale, then beat in the egg and milk.', 'On low speed add the flour gradually, until the dough pulls away from the sides of the bowl.', 'Halve the dough, wrap each piece and chill for 2 hours.', 'Heat the oven to 190°C and line trays with parchment.', 'Dust the counter and rolling pin with icing sugar instead of flour. Roll one piece of dough 6 mm thick, moving it often so it does not stick. If it warms up and softens, chill it for 10 minutes.', 'Cut shapes and set them 2.5 cm apart on the trays. Bake 7 to 9 minutes, turning the tray halfway, until the edges just start to brown.', 'Rest 2 minutes on the tray, then cool on a rack. Leave plain or ice once cold.']::text[], '{"name":"Food Network","url":"https://www.foodnetwork.com/recipes/alton-brown/sugar-cookies-recipe-1914697"}'::jsonb, false, null),
  (9, 'Chocolate Crinkle Cookies', 'cookies', 'medium', 20, 11, 72, null, null, array['vegetarian']::text[], '[{"name":"bittersweet chocolate, chopped","amount":227,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":135,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"espresso powder (optional)","amount":4,"unit":"g"},{"name":"baking powder","amount":2,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"all-purpose flour","amount":200,"unit":"g"},{"name":"icing sugar for coating","amount":120,"unit":"g"}]'::jsonb, array['Melt the chocolate and butter together and stir smooth.', 'Beat the sugar, eggs, vanilla and espresso powder, then mix in the chocolate, baking powder, salt and flour.', 'Chill 2 to 3 hours or overnight until firm.', 'Heat the oven to 165°C and line trays.', 'Roll 3 cm balls of dough and coat them thickly in icing sugar.', 'Place 4 cm apart and bake 10 to 12 minutes, turning the trays halfway, until they flatten and crack.', 'Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/chocolate-crinkle-cookies-recipe"}'::jsonb, false, null),
  (10, 'Jam Thumbprint Cookies', 'cookies', 'medium', 30, 23, 32, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":340,"unit":"g"},{"name":"sugar","amount":200,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":440,"unit":"g"},{"name":"kosher salt","amount":1,"unit":"g"},{"name":"egg, beaten with a spoonful of water, for coating","amount":1,"unit":"count"},{"name":"sweetened flaked coconut","amount":198,"unit":"g"},{"name":"raspberry or apricot jam","amount":55,"unit":"g"}]'::jsonb, array['Beat the soft butter and sugar until just combined, then mix in the vanilla.', 'Sift the flour and salt together and add to the butter on low speed, until the dough starts to come together.', 'Tip onto a floured surface, press into a flat disc, wrap and chill 30 minutes.', 'Heat the oven to 175°C.', 'Roll the dough into 3 cm balls of about 28 g each. Dip each ball in the beaten egg, then roll it in the coconut.', 'Set on an ungreased tray and press a shallow dent into each with a fingertip. Fill each dent with about a quarter teaspoon of jam.', 'Bake 20 to 25 minutes, until the coconut is golden brown. Cool before serving.']::text[], '{"name":"Food Network","url":"https://www.foodnetwork.com/recipes/ina-garten/jam-thumbprint-cookies-recipe-1956592"}'::jsonb, false, null),
  (11, 'Linzer Cookies', 'cookies', 'hard', 45, 10, 28, null, null, array['vegetarian']::text[], '[{"name":"blanched hazelnuts, toasted","amount":100,"unit":"g"},{"name":"caster sugar","amount":125,"unit":"g"},{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"cold butter, diced","amount":200,"unit":"g"},{"name":"ground cinnamon","amount":0.7,"unit":"g"},{"name":"salt","amount":0.7,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"icing sugar, for dusting","amount":15,"unit":"g"},{"name":"redcurrant jelly","amount":80,"unit":"g"},{"name":"seedless raspberry jam","amount":80,"unit":"g"}]'::jsonb, array['Blitz the hazelnuts and sugar in a food processor until as fine as sand. Add the flour, then the cold butter, cinnamon, salt, egg and yolk, and run until the dough clumps together.', 'Divide into 4 flat discs, wrap and chill for at least 1 hour.', 'Take two discs out about 15 minutes before rolling. Heat the oven to 180°C and line two trays with parchment.', 'Roll one disc 2 to 3 mm thick on a floured sheet of parchment and cut rounds with a 6 cm cutter. These are the bases.', 'Roll the second disc and cut the same rounds, then cut a small shape out of the middle of each to make the tops. Re-roll the scraps. Chill the cut cookies 10 minutes if the kitchen is warm.', 'Bake 9 to 10 minutes, until just pale gold at the edges, and move to a rack straight away. Repeat with the other two discs.', 'When cold, dust the tops with icing sugar. Stir the jelly and jam together until smooth, spread about half a teaspoon on each base and press a top onto it.']::text[], '{"name":"Nigella Lawson","url":"https://www.nigella.com/recipes/linzer-cookies"}'::jsonb, false, null),
  (12, 'Crisscross Peanut Butter Cookies', 'cookies', 'easy', 20, 11, 28, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":302,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"baking powder","amount":1,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"butter","amount":170,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"light brown sugar","amount":150,"unit":"g"},{"name":"creamy peanut butter","amount":200,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"sugar, for rolling","amount":67,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line trays with parchment.', 'Whisk the flour, baking soda, baking powder and salt.', 'Beat the butter with the sugar and brown sugar for about 2 minutes until smooth, scraping the bowl.', 'Beat in the peanut butter, then the egg and vanilla.', 'Add the flour mixture gradually on low speed, mixing until just combined.', 'Scoop balls of about 1.5 tablespoons, roll them smooth, then roll in the extra sugar. Set 5 cm apart and press a fork into each twice to make a crisscross.', 'Bake 10 to 12 minutes, until the edges are slightly browned. Cool 10 minutes on the tray, then on a rack.']::text[], '{"name":"Handle the Heat","url":"https://handletheheat.com/peanut-butter-cookies/"}'::jsonb, false, null),
  (13, 'American-Style Vanilla Biscotti', 'cookies', 'medium', 15, 55, 35, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":85,"unit":"g"},{"name":"sugar","amount":131,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"vanilla extract","amount":10,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line a large tray.', 'Beat the butter, sugar, salt, vanilla and baking powder until creamy.', 'Beat in the eggs, then mix in the flour on low to a sticky dough.', 'With wet hands, shape two logs about 24 x 5 cm on the tray.', 'Bake 25 minutes, then lower the oven to 165°C.', 'Mist the hot logs with water, wait 5 minutes, then slice straight down into 1.5 to 2 cm pieces.', 'Stand the slices on their edges and bake 25 to 30 minutes more until dry and golden. Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/american-style-vanilla-biscotti-recipe"}'::jsonb, false, null),
  (14, 'No-Knead Crusty Bread', 'bread', 'easy', 10, 42, 10, null, null, array['vegetarian']::text[], '[{"name":"bread flour","amount":450,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"very warm water","amount":375,"unit":"g"}]'::jsonb, array['Mix the flour, yeast and salt in a large bowl. Add the water (very warm from the tap, no hotter than 55°C) and stir until no dry flour is left. The dough is wet and sticky, too loose to knead.', 'Cover and leave at room temperature for 2 to 3 hours, until doubled, bubbly on top and wobbly.', 'Put a lidded cast-iron pot of about 26 cm in the oven and heat both to 230°C for 30 minutes.', 'Scrape the dough onto a floured surface and dust the top with flour. Fold the edges into the middle about six times to make a rough round.', 'Turn it seam side down onto a sheet of parchment and nudge it into a round.', 'Lift the dough on its parchment into the hot pot, cover and bake 30 minutes.', 'Take off the lid and bake 12 minutes more, until deep golden and crisp. Cool on a rack for 10 minutes before slicing.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/easy-yeast-bread-recipe-no-knead/"}'::jsonb, false, null),
  (15, 'Classic Challah', 'bread', 'medium', 20, 28, 16, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":495,"unit":"g"},{"name":"water","amount":170,"unit":"g"},{"name":"vegetable oil","amount":74,"unit":"g"},{"name":"honey","amount":63,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"salt","amount":9,"unit":"g"},{"name":"instant yeast","amount":12,"unit":"g"},{"name":"egg white, for glazing","amount":1,"unit":"count"},{"name":"poppy or sesame seeds (optional)","amount":5,"unit":"g"}]'::jsonb, array['Mix and knead the flour, water, oil, honey, eggs, yolk, salt and yeast into a soft, smooth dough. If very sticky, work in up to 30 g more flour.', 'Cover and rise about 2 hours until puffy.', 'Deflate, divide into three, and roll each piece into a 50 cm rope. Rest 10 minutes if they spring back.', 'Braid the ropes and set the loaf on a lined tray.', 'Cover and rise 60 to 90 minutes until very puffy. Heat the oven to 190°C.', 'Beat the egg white with a spoonful of cold water, brush over the loaf and add seeds.', 'Bake 25 to 30 minutes until deep golden and 88°C inside. Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-challah-recipe"}'::jsonb, false, null),
  (16, 'Whole Wheat and Rye Sourdough Loaf', 'bread', 'medium', 22, 26, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":4.5,"unit":"g"},{"name":"milk","amount":198,"unit":"g"},{"name":"sourdough starter","amount":227,"unit":"g"},{"name":"dark brown sugar","amount":28,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"caraway seeds","amount":3,"unit":"g"},{"name":"anise seeds","amount":2,"unit":"g"},{"name":"ground cardamom","amount":0.5,"unit":"g"},{"name":"rye flour","amount":53,"unit":"g"},{"name":"whole wheat flour","amount":57,"unit":"g"},{"name":"all-purpose flour","amount":225,"unit":"g"}]'::jsonb, array['Mix the yeast, lukewarm milk, starter, sugar, salt, seeds and cardamom. Beat in the rye flour until smooth.', 'Stir in the whole wheat flour, then add the all-purpose flour a little at a time until the dough is shaggy.', 'Knead about 8 minutes until smooth, elastic and just slightly tacky.', 'Rise in a covered greased bowl until doubled, 1.5 to 2 hours.', 'Deflate and shape into a round, an oval or a loaf for a 23 cm tin. Rise 45 to 60 minutes until puffy.', 'Heat the oven to 200°C.', 'Bake about 25 minutes until deep brown and hollow-sounding underneath. Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/marilyns-whole-wheat-and-rye-sourdough-bread-recipe"}'::jsonb, false, null),
  (17, 'Ultimate Banana Bread', 'quick bread', 'easy', 15, 60, 10, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"butter","amount":115,"unit":"g"},{"name":"light brown sugar","amount":190,"unit":"g"},{"name":"ripe bananas, mashed","amount":510,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":5,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"ground nutmeg (optional)","amount":0.5,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":260,"unit":"g"},{"name":"turbinado sugar, for the top","amount":25,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and butter a 23 x 13 cm loaf tin.', 'Melt the butter in a large bowl. Whisk in the brown sugar until smooth, then stir in the mashed banana.', 'Whisk in the eggs and vanilla.', 'Sprinkle the salt, cinnamon, nutmeg, baking soda and baking powder over the batter and whisk well so no pockets are left.', 'Stir in the flour until just combined.', 'Scrape into the tin, which will be nearly full, and scatter the turbinado sugar over the top.', 'Bake 55 to 65 minutes, until a skewer comes out with no wet batter. Test near the top as well, where it sets last. The crust turns very dark.', 'Cool in the tin. It slices best the next day.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2020/03/ultimate-banana-bread/"}'::jsonb, false, null),
  (18, 'Simple Zucchini Bread', 'quick bread', 'easy', 10, 60, 10, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"light brown sugar","amount":159,"unit":"g"},{"name":"milk or fruit juice","amount":28,"unit":"g"},{"name":"vegetable oil","amount":99,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"baking powder","amount":1,"unit":"g"},{"name":"baking soda","amount":2,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"all-purpose flour","amount":210,"unit":"g"},{"name":"grated zucchini","amount":270,"unit":"g"},{"name":"walnuts, toasted and chopped","amount":85,"unit":"g"},{"name":"raisins or currants","amount":128,"unit":"g"},{"name":"brown sugar, for topping","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease the tin.', 'Beat the sugar, liquid, oil, eggs and vanilla until smooth.', 'Whisk the baking powder, soda, salt and cinnamon into the flour, then fold gently into the wet mix.', 'Pat the grated zucchini dry and fold it in with the walnuts and raisins.', 'Spread in the tin and sprinkle with the topping sugar.', 'Bake 55 to 65 minutes until a skewer comes out clean.', 'Cool 10 minutes in the tin, then fully on a rack before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/simple-zucchini-bread-recipe"}'::jsonb, false, null),
  (19, 'Old-Fashioned Sandwich Loaf', 'bread', 'medium', 25, 45, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"bread flour","amount":500,"unit":"g"},{"name":"instant yeast","amount":7,"unit":"g"},{"name":"sugar","amount":8,"unit":"g"},{"name":"salt","amount":12,"unit":"g"},{"name":"cold milk","amount":125,"unit":"g"},{"name":"cold water","amount":150,"unit":"g"},{"name":"boiling water","amount":100,"unit":"g"},{"name":"butter, softened","amount":45,"unit":"g"}]'::jsonb, array['Mix the flour, yeast, sugar and salt in a large bowl.', 'In a jug combine the milk (soured milk or sour cream works well here), the cold water and then the boiling water. Stir in the soft butter. It will not melt completely.', 'Pour the liquid into the flour and stir until almost all the flour is taken up. Gather into a rough ball, cover and rest 10 minutes.', 'Knead on a lightly oiled surface for just 10 seconds, shape into a ball, cover and rest 10 minutes. Do this twice more, then cover and leave for 1 hour.', 'Grease a 23 x 13 cm loaf tin and line the base. Pat the dough into a rectangle about 2 cm thick and a little narrower than the tin, roll it up tightly and set it seam side down in the tin.', 'Rise 1 to 1.5 hours, until the dough peeks just above the rim. Heat the oven to 200°C towards the end.', 'Dust the top with flour and bake 45 minutes, until risen and deep golden. Turn out straight away and cool on a rack before slicing.']::text[], '{"name":"Nigella Lawson","url":"https://www.nigella.com/recipes/old-fashioned-sandwich-loaf"}'::jsonb, false, null),
  (20, 'Rosemary Focaccia', 'bread', 'medium', 40, 25, 10, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"warm water","amount":415,"unit":"g"},{"name":"sugar","amount":8,"unit":"g"},{"name":"active dry yeast","amount":7,"unit":"g"},{"name":"all-purpose flour","amount":500,"unit":"g"},{"name":"salt","amount":12,"unit":"g"},{"name":"extra-virgin olive oil","amount":80,"unit":"g"},{"name":"flaky sea salt","amount":2,"unit":"g"},{"name":"fresh rosemary, chopped (optional)","amount":2,"unit":"g"}]'::jsonb, array['Stir the warm water (40 to 46°C) and sugar together in a mixer bowl, sprinkle on the yeast and leave 5 minutes until foamy.', 'Add the flour and salt. Mix with a dough hook on low until shaggy, then on medium for 5 minutes. The dough is very sticky and stretchy.', 'Pour about a third of the oil into a large bowl, scrape in the dough and brush the oil over its top. Cover and rise 1 to 1.5 hours until doubled.', 'Oil a 33 x 23 cm tin with another third of the oil. With oiled hands, fold the edges of the dough into the middle to make a rough ball and move it to the tin, turning it to coat.', 'Press the dough towards the corners. When it springs back, let it rest a few minutes and press again. Cover and rise about 45 minutes until doubled. Heat the oven to 220°C partway through.', 'Drizzle with the rest of the oil and, with oiled fingers, press deep dimples all the way down to the tin. Scatter with flaky salt and rosemary.', 'Bake 20 to 30 minutes until golden brown. Cool a little before slicing.']::text[], '{"name":"Love and Lemons","url":"https://www.loveandlemons.com/focaccia/"}'::jsonb, false, null),
  (21, 'Cinnamon Raisin Bread', 'bread', 'medium', 15, 43, 12, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"milk","amount":170,"unit":"g"},{"name":"butter","amount":28,"unit":"g"},{"name":"raisins","amount":85,"unit":"g"},{"name":"rolled oats","amount":45,"unit":"g"},{"name":"light brown sugar","amount":50,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"instant yeast","amount":8,"unit":"g"},{"name":"water","amount":65,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"cinnamon sugar, for the top","amount":15,"unit":"g"}]'::jsonb, array['Mix and knead the milk, butter, raisins, oats, sugar, salt, cinnamon, yeast, water and flour into a smooth, soft dough.', 'Rise about 2 hours until puffy.', 'Shape into a log, place in a greased tin and tent. Rise 1.5 to 2 hours until it crowns 3 to 4 cm over the rim. Heat the oven to 175°C.', 'Brush the top with milk or water and sprinkle with cinnamon sugar.', 'Bake 40 to 45 minutes until deep golden and 88°C inside. Cover with foil if browning too quickly.', 'Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cinnamon-raisin-bread-recipe"}'::jsonb, false, null),
  (22, 'Classic Sandwich Bread', 'bread', 'easy', 12, 33, 12, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"milk","amount":113,"unit":"g"},{"name":"hot water","amount":130,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"}]'::jsonb, array['Mix everything and knead to a smooth, soft dough: by hand, with a stand mixer for 5 to 7 minutes, or on a bread machine''s dough cycle.', 'Rise 1 to 2 hours until puffy.', 'Deflate gently and shape into a 20 cm log.', 'Place in a greased tin and rise about 1 hour until domed 2.5 cm above the rim. Heat the oven to 175°C.', 'Bake 30 to 35 minutes until light golden and 88°C in the centre.', 'Cool on a rack before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-sandwich-bread-recipe"}'::jsonb, false, null),
  (23, 'Pumpkin Bread', 'quick bread', 'easy', 15, 70, 8, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"pumpkin purée","amount":425,"unit":"g"},{"name":"vegetable oil","amount":115,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"sugar","amount":330,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"baking soda","amount":4.5,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"ground cinnamon","amount":2,"unit":"g"},{"name":"ground nutmeg","amount":0.7,"unit":"g"},{"name":"ground ginger","amount":0.6,"unit":"g"},{"name":"ground cloves","amount":0.2,"unit":"g"},{"name":"all-purpose flour","amount":295,"unit":"g"},{"name":"sugar, for the top","amount":12,"unit":"g"},{"name":"ground cinnamon, for the top","amount":3,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and butter a 23 x 13 cm loaf tin.', 'Whisk the pumpkin, oil, eggs and sugar in a large bowl until smooth.', 'Sprinkle the baking powder, baking soda, salt and spices over the batter and whisk until fully combined.', 'Stir in the flour with a spoon, just until no dry flour is left.', 'Scrape into the tin and smooth the top.', 'Mix the topping sugar and cinnamon and sprinkle evenly over the batter.', 'Bake 65 to 75 minutes, turning the tin once, until a skewer comes out free of batter everywhere, including just under the top.', 'Cool in the tin for at least 10 minutes before turning out.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2016/10/pumpkin-bread/"}'::jsonb, false, null),
  (24, 'Honey Cornbread', 'bread', 'easy', 15, 30, 9, 'square-20', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":125,"unit":"g"},{"name":"cornmeal","amount":140,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking soda","amount":1.5,"unit":"g"},{"name":"milk","amount":240,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"honey","amount":42,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 20 cm square dish.', 'Whisk the flour, cornmeal, baking powder, salt and baking soda in a large bowl.', 'Whisk the milk (or buttermilk), egg, melted butter, sugar and honey in another bowl.', 'Pour the wet ingredients into the dry and mix until just combined.', 'Scrape into the dish and smooth the top.', 'Bake 25 to 35 minutes, until the top springs back when pressed and a skewer comes out clean.', 'Cool 20 minutes in the dish before slicing.']::text[], '{"name":"Love and Lemons","url":"https://www.loveandlemons.com/cornbread-recipe/"}'::jsonb, false, null),
  (25, 'Golden Vanilla Pound Cake', 'cake', 'easy', 10, 65, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"butter","amount":170,"unit":"g"},{"name":"cream cheese","amount":85,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"sugar","amount":298,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"almond extract","amount":4,"unit":"g"},{"name":"eggs","amount":5,"unit":"count"},{"name":"milk","amount":43,"unit":"g"},{"name":"all-purpose flour","amount":226,"unit":"g"},{"name":"sugar, for the glaze","amount":25,"unit":"g"},{"name":"vanilla extract, for the glaze","amount":4,"unit":"g"},{"name":"water, for the glaze","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and lightly grease the tin.', 'Beat the butter, cream cheese, salt, sugar, baking powder and both extracts until smooth.', 'Add the eggs one at a time. After the last, beat on high for 3 minutes, then stir in the milk.', 'Mix in the flour on low speed until just combined and scrape into the tin.', 'Stir the glaze ingredients into a drizzly syrup.', 'Set the tin on a tray and bake 55 minutes, brush with the glaze, then bake 15 to 20 minutes more until a skewer comes out clean (about 95°C in the centre).', 'Cool 5 minutes, turn out and cool completely.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/golden-vanilla-pound-cake-recipe"}'::jsonb, false, null),
  (26, 'Strawberry Summer Cake', 'cake', 'easy', 20, 65, 9, 'round-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":188,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"butter","amount":85,"unit":"g"},{"name":"sugar","amount":200,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"milk","amount":120,"unit":"g"},{"name":"vanilla extract","amount":5,"unit":"g"},{"name":"strawberries, hulled and halved","amount":450,"unit":"g"},{"name":"sugar, for the top","amount":25,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and butter a 23 cm springform tin or deep pie dish.', 'Whisk the flour, baking powder and salt.', 'In a larger bowl, beat the soft butter with the 200 g of sugar until pale and fluffy, about 3 minutes.', 'Mix in the egg, milk and vanilla until just combined, then add the flour mixture a little at a time until smooth.', 'Spread the batter in the tin. Cover it with the strawberries, cut side down and packed close together, then sprinkle with the topping sugar.', 'Bake 10 minutes, lower the oven to 165°C and bake 50 to 60 minutes more, until golden and a skewer comes out free of wet batter.', 'Cool in the tin on a rack and cut into wedges.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2011/05/strawberry-summer-cake/"}'::jsonb, false, null),
  (27, 'Mom''s Apple Cake', 'cake', 'medium', 30, 90, 12, null, null, array['vegetarian']::text[], '[{"name":"apples, peeled and chopped","amount":6,"unit":"count"},{"name":"ground cinnamon","amount":8,"unit":"g"},{"name":"sugar, for the apples","amount":65,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"vegetable oil","amount":215,"unit":"g"},{"name":"orange juice","amount":60,"unit":"g"},{"name":"sugar","amount":400,"unit":"g"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"walnuts, chopped (optional)","amount":130,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a tube tin.', 'Peel and core the apples, cut them into 2.5 cm chunks and toss them with the cinnamon and the 65 g of sugar.', 'Stir the flour, baking powder and salt together in a large bowl.', 'Whisk the oil, orange juice, sugar, vanilla and eggs in another bowl, then mix into the dry ingredients until smooth. Stir in the walnuts if using.', 'Pour half the batter into the tin and cover with half the apples and their juice. Add the rest of the batter and finish with the remaining apples.', 'Bake about 1.5 hours, until a skewer pushed in below the top apples comes out clean. Cover with foil if the top browns too quickly.', 'Cool completely, loosen the edges with a knife and turn out.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2008/09/moms-apple-cake/"}'::jsonb, false, null),
  (28, 'Chocolate Olive Oil Cake', 'cake', 'easy', 10, 26, 9, 'square-23', null, array['vegetarian']::text[], '[{"name":"cake flour","amount":210,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"black cocoa","amount":11,"unit":"g"},{"name":"cocoa powder","amount":11,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking soda","amount":3.5,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"cider vinegar","amount":14,"unit":"g"},{"name":"extra-virgin olive oil","amount":150,"unit":"g"},{"name":"water","amount":151,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"chocolate chips, for the topping","amount":57,"unit":"g"},{"name":"sugar, for the topping","amount":25,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 23 cm square tin.', 'Whisk the flour, sugar, both cocoas, salt and baking soda.', 'Whisk the vanilla, vinegar, oil, water and eggs in another bowl, then combine with the dry mix and pour into the tin.', 'Bake 24 to 28 minutes until a skewer comes out clean or with a few moist crumbs.', 'Meanwhile grind the topping chocolate finely and mix with the topping sugar.', 'As soon as the cake leaves the oven, scatter the chocolate mix over the top.', 'Return it to the oven for about 1 minute until the topping softens and settles.', 'Cool until cool to the touch, then chill 10 to 15 minutes until the topping sets.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/chocolate-olive-oil-cake-recipe"}'::jsonb, false, null),
  (29, 'Traditional Angel Food Cake', 'cake', 'hard', 20, 43, 16, null, null, array['vegetarian']::text[], '[{"name":"cake flour","amount":120,"unit":"g"},{"name":"sugar","amount":298,"unit":"g"},{"name":"egg whites","amount":12,"unit":"count"},{"name":"salt","amount":3,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"cream of tartar","amount":4,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C. Do not grease the tube tin.', 'Whisk the flour with half of the sugar and set aside.', 'Beat the egg whites, salt and vanilla until frothy. Add the cream of tartar and beat to stiff, glossy peaks.', 'Beat in the remaining sugar a little at a time, then fold in the flour mixture gradually.', 'Spoon into the tin and bake 40 to 45 minutes until golden and the top springs back.', 'Turn the tin upside down over a bottle neck and cool for 1.5 hours.', 'Loosen the edges with a knife and ease the cake out.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/traditional-angel-food-cake-recipe"}'::jsonb, false, null),
  (30, 'Purple Plum Torte', 'cake', 'easy', 15, 48, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"butter","amount":115,"unit":"g"},{"name":"sugar","amount":200,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":130,"unit":"g"},{"name":"baking powder","amount":5,"unit":"g"},{"name":"salt","amount":1,"unit":"g"},{"name":"small purple plums, halved and pitted","amount":12,"unit":"count"},{"name":"lemon juice","amount":10,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"sugar, for the top","amount":15,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 23 cm springform tin.', 'Beat the soft butter and the 200 g of sugar until pale and fluffy, then beat in the eggs one at a time, scraping the bowl.', 'Sift the flour, baking powder and salt over the batter and mix until just combined.', 'Spread the batter in the tin. Arrange the plum halves on top, skin side up and close together, so they cover the batter.', 'Sprinkle with the lemon juice, then the cinnamon, then the topping sugar (use less if the plums are sweet).', 'Bake 45 to 50 minutes, until golden and a skewer in the centre comes out free of batter. Cool on a rack.', 'It is even better the next day, once the plum juices have soaked into the cake.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2013/10/purple-plum-torte/"}'::jsonb, false, null),
  (31, 'Lemon Buttermilk Pound Cake', 'cake', 'medium', 25, 60, 16, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":390,"unit":"g"},{"name":"baking soda","amount":3,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"buttermilk","amount":240,"unit":"g"},{"name":"lemon zest","amount":12,"unit":"g"},{"name":"lemon juice","amount":30,"unit":"g"},{"name":"butter","amount":226,"unit":"g"},{"name":"sugar","amount":450,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"water, for the syrup","amount":30,"unit":"g"},{"name":"sugar, for the syrup","amount":25,"unit":"g"},{"name":"lemon juice, for the syrup","amount":10,"unit":"g"},{"name":"icing sugar, for the glaze","amount":115,"unit":"g"},{"name":"lemon juice, for the glaze","amount":30,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Grease two 22 x 11 cm loaf tins and line each with a strip of parchment that hangs over the long sides.', 'Whisk the flour, baking soda and salt in one bowl. Stir the buttermilk, lemon zest and lemon juice together in another.', 'Beat the soft butter and sugar for 3 to 4 minutes until pale and fluffy, then beat in the eggs one at a time, scraping the bowl.', 'On low speed add the flour in four parts and the buttermilk in three, starting and ending with flour and mixing only briefly each time.', 'Divide between the tins and bake 55 to 65 minutes, until golden and a skewer comes out clean. Cool 10 minutes in the tins, then lift out and cool for about an hour.', 'For the syrup, boil the water and sugar, take off the heat and add the lemon juice. Brush the warm syrup all over the cooled cakes, sides included.', 'Whisk the icing sugar and lemon juice into a thick but pourable glaze, spoon it over the tops and leave about an hour to set.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/lemon-buttermilk-pound-cake.html"}'::jsonb, false, null),
  (32, 'Perfect Blueberry Muffins', 'muffins', 'easy', 15, 28, 9, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":70,"unit":"g"},{"name":"sugar","amount":100,"unit":"g"},{"name":"lemon zest","amount":2,"unit":"g"},{"name":"plain yogurt or sour cream","amount":180,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"baking powder","amount":7,"unit":"g"},{"name":"baking soda","amount":1.5,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"all-purpose flour","amount":195,"unit":"g"},{"name":"blueberries, fresh or frozen","amount":235,"unit":"g"},{"name":"turbinado sugar, for the top","amount":35,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line 9 cups of a muffin tin with paper cases.', 'Melt the butter in the bottom of a large bowl.', 'Whisk in the sugar, lemon zest, yogurt and egg until smooth.', 'Whisk in the baking powder, baking soda and salt until fully mixed in.', 'Gently fold in the flour and blueberries (frozen ones can go in straight from the freezer). The batter is very thick, like cookie dough.', 'Divide between the 9 cups and sprinkle each with about a teaspoon of turbinado sugar.', 'Bake 25 to 30 minutes, until golden and a skewer comes out clean. Cool 10 minutes in the tin, then on a rack.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2010/08/perfect-blueberry-muffins/"}'::jsonb, false, null),
  (33, 'Bran Muffins', 'muffins', 'easy', 15, 26, 12, null, null, array['vegetarian']::text[], '[{"name":"boiling water","amount":113,"unit":"g"},{"name":"wheat bran, for soaking","amount":43,"unit":"g"},{"name":"vegetable oil","amount":67,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"raisins","amount":128,"unit":"g"},{"name":"buttermilk","amount":283,"unit":"g"},{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"bran cereal","amount":128,"unit":"g"}]'::jsonb, array['Pour the boiling water over the wheat bran. When cool, stir in the oil and egg.', 'Whisk the flour, sugar, baking soda, baking powder and salt, then stir in the raisins.', 'Mix the buttermilk and brown sugar into the dry ingredients, then add the bran cereal and the soaked bran mixture.', 'Cover and refrigerate overnight.', 'Heat the oven to 190°C and line or grease a 12-cup muffin tin.', 'Stir the batter and fill each cup generously.', 'Bake 22 to 27 minutes until a skewer comes out clean. Cool 10 minutes in the tin, then remove.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/bran-muffins-recipe"}'::jsonb, false, null),
  (34, 'The Simplest Muffins', 'muffins', 'easy', 7, 17, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"quick-cooking oats","amount":45,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"ground cinnamon (optional)","amount":3,"unit":"g"},{"name":"dried fruit, nuts or chocolate chips","amount":170,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"}]'::jsonb, array['Heat the oven to 220°C and grease a 12-cup muffin tin or line it with greased papers.', 'Mix the flour, oats, sugar, salt, baking powder, cinnamon and add-ins in a bowl.', 'Whisk the milk, vanilla, melted butter and eggs in another bowl.', 'Combine the wet and dry just until blended.', 'Fill each cup about three-quarters full.', 'Bake 15 to 18 minutes until set and lightly golden.', 'Rest 5 minutes in the tin, then cool on a rack. Best warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/the-simplest-muffins-recipe"}'::jsonb, false, null),
  (35, 'Pumpkin Muffins with Pecan Streusel', 'muffins', 'easy', 15, 37, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour, for the topping","amount":40,"unit":"g"},{"name":"butter, melted, for the topping","amount":70,"unit":"g"},{"name":"demerara sugar","amount":65,"unit":"g"},{"name":"pecans, chopped","amount":85,"unit":"g"},{"name":"ground cinnamon, for the topping","amount":0.7,"unit":"g"},{"name":"all-purpose flour","amount":260,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":2,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"ground cloves","amount":2,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"ground nutmeg","amount":2,"unit":"g"},{"name":"butter","amount":170,"unit":"g"},{"name":"sugar","amount":300,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"pumpkin purée","amount":425,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 12-cup muffin tin.', 'Stir the topping flour, melted butter, demerara sugar, pecans and cinnamon together. It should be wet and clumpy.', 'Whisk the 260 g of flour with the salt, baking powder, baking soda, cloves, cinnamon and nutmeg.', 'Beat the soft butter and sugar on low until just blended. Add the eggs one at a time, then keep beating a few minutes until very light and fluffy.', 'Beat in the pumpkin, scraping the bowl, then mix in the flour mixture on low until just combined.', 'Fill each cup right to the top and scatter the topping over with your fingers.', 'Bake 35 to 40 minutes, until a skewer comes out clean. Cool 10 minutes in the tin, then on a rack.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/pumpkin-muffins.html"}'::jsonb, false, null),
  (36, 'Lemon Poppy Seed Muffins', 'muffins', 'easy', 7, 19, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"yellow cornmeal","amount":46,"unit":"g"},{"name":"lemon juice powder","amount":21,"unit":"g"},{"name":"poppy seeds","amount":28,"unit":"g"},{"name":"baking powder","amount":9,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"butter, melted","amount":113,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"icing sugar, for the glaze","amount":113,"unit":"g"},{"name":"lemon juice powder, for the glaze","amount":7,"unit":"g"},{"name":"milk, for the glaze","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and grease a 12-cup muffin tin or line it with papers.', 'Whisk the flour, sugar, cornmeal, lemon juice powder, poppy seeds, baking powder and salt.', 'Whisk the milk, eggs, melted butter and vanilla in another bowl.', 'Stir the wet into the dry just until moistened and fill the cups almost to the top.', 'Bake 18 to 20 minutes until a skewer comes out clean. Rest 5 minutes, then move to a rack.', 'Stir the glaze ingredients, adding sugar or milk until spreadable.', 'Spread over the warm muffins and let it set.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/lemon-poppy-seed-muffins-recipe"}'::jsonb, false, null),
  (37, 'Fudge Brownies', 'bars', 'easy', 12, 30, 24, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"eggs","amount":4,"unit":"count"},{"name":"Dutch-process cocoa","amount":106,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"espresso powder (optional)","amount":2,"unit":"g"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"butter","amount":227,"unit":"g"},{"name":"sugar","amount":447,"unit":"g"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"chocolate chips","amount":340,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 33 x 23 cm tin (line with parchment so you can lift the brownies out).', 'Beat the eggs, cocoa, salt, baking powder, espresso powder and vanilla until thick and mostly smooth.', 'Melt the butter, stir in the sugar and warm to 45 to 50°C without bubbling. Partly dissolved sugar gives the shiny top.', 'Stir the warm butter and sugar into the egg mixture until smooth.', 'Fold in the flour and chocolate chips, scraping the bowl well.', 'Spread evenly in the tin and bake 28 to 32 minutes until the edges are set and a skewer shows moist crumbs, not raw batter.', 'Cool completely before cutting.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/fudge-brownies-recipe"}'::jsonb, false, null),
  (38, 'Best Cocoa Brownies', 'bars', 'easy', 15, 30, 16, 'square-20', null, array['vegetarian']::text[], '[{"name":"butter","amount":140,"unit":"g"},{"name":"sugar","amount":250,"unit":"g"},{"name":"cocoa powder","amount":65,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":65,"unit":"g"},{"name":"walnuts or pecans, chopped (optional)","amount":75,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C with a rack in the lower third. Line a 20 cm square tin with parchment, leaving two sides hanging over the edge.', 'Put the butter, sugar, cocoa and salt in a heatproof bowl over a pan of barely simmering water. Stir now and then until the butter has melted and the mixture is hot and smooth. It will look grainy.', 'Take the bowl off the heat and let it cool until just warm.', 'Stir in the vanilla, then the cold eggs one at a time, beating hard after each until the batter turns thick and glossy.', 'Stir in the flour until it disappears, then beat about 40 strokes more. Fold in the nuts if using.', 'Spread in the tin and bake 25 to 35 minutes, until a skewer in the centre comes out with a little moist batter on it.', 'Cool completely in the tin (chilling gives cleaner cuts), lift out by the parchment and cut into 16 squares.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2010/01/best-cocoa-brownies/"}'::jsonb, false, null),
  (39, 'Brown Butter Blondies', 'bars', 'easy', 15, 23, 16, 'square-20', null, array['vegetarian']::text[], '[{"name":"butter","amount":115,"unit":"g"},{"name":"light brown sugar","amount":190,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"flaky sea salt","amount":1.5,"unit":"g"},{"name":"all-purpose flour","amount":130,"unit":"g"},{"name":"chocolate chips","amount":170,"unit":"g"},{"name":"walnuts, toasted and chopped","amount":60,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Line a 20 cm square tin with parchment and butter any bare sides.', 'Melt the butter in a small pan and keep cooking, stirring now and then, until the bits at the bottom turn brown and it smells toasty. Pour into a mixing bowl.', 'Whisk in the brown sugar until smooth and let it cool to lukewarm.', 'Whisk in the egg, vanilla and salt.', 'Stir in the flour, then the chocolate chips and walnuts (or 230 g of any mix-ins you like).', 'Scrape the thick batter into the tin and smooth the top.', 'Bake 20 to 25 minutes, until the edges are lightly browned and the centre still looks a little underbaked. Cool, lift out and cut into 16 squares.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2006/11/blondies/"}'::jsonb, false, null),
  (40, 'Luscious Lemon Bars', 'bars', 'medium', 30, 50, 20, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":230,"unit":"g"},{"name":"cornstarch","amount":30,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"icing sugar","amount":115,"unit":"g"},{"name":"cold butter, cubed","amount":226,"unit":"g"},{"name":"eggs","amount":6,"unit":"count"},{"name":"sugar","amount":600,"unit":"g"},{"name":"lemon juice","amount":160,"unit":"g"},{"name":"lemon zest","amount":12,"unit":"g"},{"name":"all-purpose flour, for the topping","amount":85,"unit":"g"},{"name":"icing sugar, for dusting","amount":10,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Line a 33 x 23 cm metal tin with foil, pressing it into the corners, and grease the foil.', 'Pulse the 230 g of flour, cornstarch, salt and icing sugar in a food processor. Add the cold butter and pulse 10 to 15 seconds, until it looks like coarse meal.', 'Press the crumbs into the tin in an even layer, pushing them about 2 cm up the sides. Chill 30 minutes.', 'Bake the crust 15 to 20 minutes until lightly golden.', 'Whisk the eggs, sugar, lemon juice, zest and the 85 g of flour until no lumps remain.', 'Stir the filling once more, pour it over the hot crust and bake 30 to 35 minutes, until the topping is set and firm.', 'Cool to room temperature, which takes a few hours. Lift out by the foil, cut into squares and dust with icing sugar.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/luscious-lemon-bars.html"}'::jsonb, false, null),
  (41, 'Buttermilk Biscuits', 'scones', 'easy', 20, 18, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"sugar","amount":12.5,"unit":"g"},{"name":"butter","amount":85,"unit":"g"},{"name":"buttermilk","amount":240,"unit":"g"},{"name":"milk, for brushing","amount":15,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C with a rack in the upper third. Line a tray with parchment.', 'Whisk the flour, salt, baking powder and sugar.', 'Cut in the butter until the mix looks like coarse breadcrumbs.', 'Add the buttermilk and mix briefly until cohesive. If dry, add up to 28 g more.', 'Pat into a 2 cm thick rectangle, fold in thirds, and pat back to 2 cm.', 'Cut with a 6 cm cutter, or into squares to avoid scraps.', 'Place on the tray, brush with milk and bake 15 to 20 minutes until lightly browned. Serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/buttermilk-biscuits-recipe"}'::jsonb, false, null),
  (42, 'Dreamy Cream Scones', 'scones', 'easy', 15, 14, 8, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":280,"unit":"g"},{"name":"baking powder","amount":15,"unit":"g"},{"name":"sugar","amount":40,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"cold butter, cubed","amount":70,"unit":"g"},{"name":"currants or dried cranberries","amount":80,"unit":"g"},{"name":"heavy cream","amount":235,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C with a rack in the middle.', 'Whisk the flour, baking powder, sugar and salt in a large bowl.', 'Cut or rub in the cold butter until the mixture looks like coarse meal with a few larger lumps, then stir in the currants.', 'Stir in the cream with a spatula until a dough starts to form, about 30 seconds.', 'Tip onto the counter and knead for 5 to 10 seconds, just until it holds together as a rough, sticky ball.', 'Pat into a 20 cm round about 2 cm thick and cut into 8 wedges.', 'Set on an ungreased tray and bake 12 to 15 minutes, until the tops are light brown. Cool on a rack for at least 10 minutes.']::text[], '{"name":"Smitten Kitchen","url":"https://smittenkitchen.com/2006/11/dream-a-little-dream-of-scone/"}'::jsonb, false, null),
  (43, 'Cheddar and Scallion Scones', 'scones', 'easy', 10, 22, 10, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"cold butter, cubed","amount":85,"unit":"g"},{"name":"sharp cheddar, grated","amount":113,"unit":"g"},{"name":"scallions, chopped","amount":30,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"milk or sour cream","amount":74,"unit":"g"},{"name":"Dijon mustard (optional)","amount":14,"unit":"g"},{"name":"hot sauce (optional)","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line a tray.', 'Mix the flour, salt and baking powder and rub in the butter until crumbly.', 'Fold in the cheese and scallions.', 'Whisk the eggs, milk, mustard and hot sauce and stir into the dry mix until just moistened. The dough is very sticky.', 'On a floured surface pat into a 25 x 5 cm rectangle.', 'Cut into 5 squares, then cut each in half diagonally to make 10 triangles.', 'Space 2.5 cm apart and bake 20 to 23 minutes until browned. Serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cheddar-cheese-and-scallion-scones-recipe"}'::jsonb, false, null),
  (44, 'Soft No-Knead Dinner Rolls', 'buns', 'easy', 20, 17, 12, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":9,"unit":"g"},{"name":"sugar","amount":55,"unit":"g"},{"name":"warm water","amount":125,"unit":"g"},{"name":"bread flour","amount":600,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"lukewarm milk","amount":255,"unit":"g"},{"name":"butter, melted and cooled","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"butter, melted, for brushing","amount":15,"unit":"g"}]'::jsonb, array['Stir the yeast and 2 teaspoons of the sugar into the warm water and leave 5 minutes until frothy.', 'Mix the flour, the rest of the sugar and the salt in a large bowl and make a well in the middle.', 'Add the milk, melted butter, beaten eggs and the yeast liquid. Stir with a wooden spoon into a thick, sticky dough. There is no kneading.', 'Cover with a damp tea towel and rise somewhere warm for 1.5 to 2 hours, until almost tripled and bubbly.', 'Punch the dough down and stir briefly. Turn out onto a floured surface, shape into a log and cut into 12 pieces.', 'Flatten each piece, gather the edges into a ball and turn it smooth side up. Set the balls in a parchment-lined 33 x 23 cm tin, three across and four down.', 'Cover loosely and rise 30 to 45 minutes, until about three-quarters bigger. Heat the oven to 200°C partway through.', 'Bake 15 to 18 minutes, until golden and the middle roll sounds hollow when tapped. Brush the hot rolls with the melted butter and cool on a rack.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/soft-no-knead-dinner-rolls/"}'::jsonb, false, null),
  (45, 'Pillowy Cinnamon Rolls', 'buns', 'medium', 30, 16, 8, null, null, array['vegetarian']::text[], '[{"name":"milk, for the tangzhong","amount":113,"unit":"g"},{"name":"bread flour, for the tangzhong","amount":24,"unit":"g"},{"name":"cold milk","amount":151,"unit":"g"},{"name":"bread flour","amount":300,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"butter, melted, for the filling","amount":14,"unit":"g"},{"name":"light brown sugar","amount":107,"unit":"g"},{"name":"bread flour, for the filling","amount":14,"unit":"g"},{"name":"ground cinnamon","amount":9,"unit":"g"},{"name":"butter, melted, for brushing and icing","amount":42,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"icing sugar","amount":170,"unit":"g"},{"name":"milk, for the icing","amount":21,"unit":"g"}]'::jsonb, array['Cook the tangzhong milk and flour over medium heat until thick and paste-like. Scrape into a mixing bowl.', 'Add the dough ingredients in order. Mix, then knead 10 to 15 minutes until smooth, elastic and tacky.', 'Rise 1 to 1.5 hours until puffy.', 'Mix the filling ingredients to a damp-sand texture.', 'Roll the dough to a 25 x 30 cm rectangle about 1 cm thick. Spread the filling, leaving a 1 cm strip bare, roll into a log and cut into 8 pieces (dental floss cuts cleanly).', 'Space the rolls at least 5 cm apart on a lined tray, tuck the ends under and proof 30 to 60 minutes until puffy.', 'Heat the oven to 190°C. Bake 14 to 18 minutes until golden and 88°C in the centre. Brush with half the melted butter and cool 10 to 15 minutes.', 'Beat the rest of the butter with the vanilla, icing sugar and enough milk for a smooth icing. Ice and serve.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/perfectly-pillowy-cinnamon-rolls-recipe"}'::jsonb, false, null),
  (46, 'Easy Hot Cross Buns', 'buns', 'medium', 25, 20, 12, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"dried fruit","amount":78,"unit":"g"},{"name":"raisins or currants","amount":78,"unit":"g"},{"name":"apple juice or rum","amount":57,"unit":"g"},{"name":"milk","amount":283,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"butter","amount":85,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"},{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"ground cloves or allspice","amount":0.6,"unit":"g"},{"name":"ground nutmeg","amount":0.6,"unit":"g"},{"name":"salt","amount":11,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"all-purpose flour","amount":540,"unit":"g"},{"name":"egg white, for glazing","amount":1,"unit":"count"},{"name":"milk, for glazing","amount":14,"unit":"g"},{"name":"icing sugar","amount":128,"unit":"g"},{"name":"vanilla extract","amount":2.5,"unit":"g"},{"name":"milk, for the icing","amount":20,"unit":"g"}]'::jsonb, array['Warm the dried fruit with the juice or rum in the microwave, then cool to room temperature.', 'Mix the milk, eggs, yolk, butter, yeast, sugar, spices, salt, baking powder and flour and knead until soft. The dough is slack, so grease your hands. Mix in the fruit.', 'Rise covered 1 hour. It may not double.', 'Divide into 12 pieces of about 106 g, round them and set them in a greased tin.', 'Cover and rise about 1 hour until the buns touch. Heat the oven to 190°C.', 'Beat the egg white with the milk and brush over the buns.', 'Bake 20 minutes until golden, then turn out onto a rack.', 'Beat the icing ingredients to a thick pipeable icing and pipe a cross on each cooled bun.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/easy-hot-cross-buns-recipe"}'::jsonb, false, null),
  (47, 'English Muffins', 'buns', 'medium', 45, 25, 6, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour, for the preferment","amount":190,"unit":"g"},{"name":"instant yeast","amount":2,"unit":"g"},{"name":"milk","amount":152,"unit":"g"},{"name":"water","amount":102,"unit":"g"},{"name":"all-purpose flour, for the dough","amount":120,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":4,"unit":"g"},{"name":"butter, melted","amount":18,"unit":"g"},{"name":"cornmeal, for dusting","amount":25,"unit":"g"}]'::jsonb, array['Whisk the preferment flour, yeast, milk and water into a thick batter and rest 1 to 4 hours until bubbly and doubled.', 'Mix in the dough flour, salt, sugar and butter to a soft, sticky dough, then do 6 to 8 bowl folds.', 'Rest 1 hour, fold again, and rest another hour until very puffy.', 'Pat to 1 cm thick on cornmeal and cut six 9 cm rounds, re-pressing the scraps.', 'Rest the rounds on cornmeal-dusted parchment for 20 to 30 minutes.', 'Cook in a preheated skillet or griddle over medium-low heat, 10 to 15 minutes per side, until browned and about 2.5 cm thick.', 'Cool on a rack, split with a fork and toast.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/english-muffins-recipe"}'::jsonb, false, null),
  (48, 'Naan', 'flatbread', 'medium', 30, 14, 8, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"bread flour","amount":90,"unit":"g"},{"name":"warm water","amount":142,"unit":"g"},{"name":"full-fat plain Greek yogurt","amount":71,"unit":"g"},{"name":"ghee or butter, melted","amount":28,"unit":"g"},{"name":"instant yeast","amount":4.5,"unit":"g"},{"name":"sugar","amount":4,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ghee or butter, melted, for brushing","amount":28,"unit":"g"},{"name":"nigella seeds (optional)","amount":4,"unit":"g"},{"name":"fresh cilantro, chopped (optional)","amount":4,"unit":"g"}]'::jsonb, array['Mix the dough ingredients into a shaggy mass, then knead until smooth, bouncy and slightly tacky.', 'Cover and rise in a greased bowl until doubled, 50 to 60 minutes.', 'Divide into 8 pieces of about 65 g, shape into balls, cover and rest 20 minutes.', 'Heat a cast-iron pan or griddle over medium-high heat.', 'Roll or stretch each ball to a 15 cm round or 18 cm oval for thicker naan, or larger for thinner.', 'Cook 30 to 40 seconds until bubbles form and the underside browns, flip and cook 40 to 50 seconds more.', 'Brush with melted ghee, add seeds and cilantro if using, and keep warm in foil or a 95°C oven.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/naan-recipe"}'::jsonb, false, null),
  (49, 'Salted Honey Butter Rolls', 'buns', 'medium', 30, 21, 15, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"butter","amount":57,"unit":"g"},{"name":"whole milk","amount":296,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"honey","amount":84,"unit":"g"},{"name":"instant yeast","amount":7,"unit":"g"},{"name":"salt","amount":9,"unit":"g"},{"name":"bread flour","amount":603,"unit":"g"},{"name":"egg, beaten, for glazing","amount":1,"unit":"count"},{"name":"butter, for the topping","amount":28,"unit":"g"},{"name":"honey, for the topping","amount":21,"unit":"g"},{"name":"flaky sea salt","amount":2,"unit":"g"}]'::jsonb, array['Melt the butter in the milk and let it cool to about 46 to 49°C: warm, but not hot enough to harm the yeast.', 'In a mixer bowl combine the milk mixture, eggs, honey, yeast and salt. Add about half the flour and mix to a shaggy dough, then add the rest a little at a time.', 'Knead with the dough hook on medium speed for about 10 minutes, until soft, smooth and stretchy. It stays a little tacky.', 'Rise in a greased bowl for 1.5 to 2 hours, until doubled.', 'Divide into 15 pieces of about 80 g, shape each into a tight ball and set seam side down in a greased 33 x 23 cm tin.', 'Cover and rise 1 to 1.5 hours, until doubled. A gentle poke should leave a dent. Heat the oven to 190°C.', 'Brush with the beaten egg and bake 20 to 22 minutes until golden brown.', 'Melt the topping butter with the honey, brush over the hot rolls and finish with flaky salt.']::text[], '{"name":"Handle the Heat","url":"https://handletheheat.com/salted-honey-butter-rolls/"}'::jsonb, false, null),
  (50, 'Chocolate Cream Pie', 'pie', 'medium', 40, 6, 9, 'round-23', null, array['vegetarian']::text[], '[{"name":"chocolate sandwich cookies","amount":24,"unit":"count"},{"name":"butter, melted","amount":70,"unit":"g"},{"name":"sugar","amount":135,"unit":"g"},{"name":"cornstarch","amount":30,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"egg yolks","amount":4,"unit":"count"},{"name":"whole milk","amount":720,"unit":"g"},{"name":"bittersweet chocolate, chopped","amount":140,"unit":"g"},{"name":"unsweetened chocolate, chopped","amount":57,"unit":"g"},{"name":"butter","amount":28,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"heavy cream","amount":235,"unit":"g"},{"name":"sugar, for the cream","amount":13,"unit":"g"},{"name":"bittersweet chocolate, grated, for the top","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Blitz the sandwich cookies with the melted butter in a food processor until fine and evenly damp.', 'Press the crumbs into a deep 23 cm pie dish, sides first, then the base. Bake 5 to 6 minutes until slightly crisp and cool completely.', 'Whisk the sugar, cornstarch and salt in a heavy saucepan. Whisk the egg yolks into the milk, then add this slowly to the pan, whisking until smooth.', 'Cook over medium-high heat for 6 to 8 minutes, whisking often and scraping the corners, until it bubbles and thickens. Lower the heat and whisk constantly for 1 minute more.', 'Off the heat, whisk in both chopped chocolates, the 28 g of butter and the vanilla until melted and smooth.', 'Pour into the cold crust, press plastic wrap directly onto the surface and chill at least 8 hours.', 'Up to 3 hours before serving, whip the cold cream until the beaters leave tracks, add the 13 g of sugar and whip to soft, silky peaks.', 'Spread the cream over the filling, leaving a border of chocolate showing, and sprinkle with the grated chocolate.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/chocolate-cream-pie.html"}'::jsonb, false, null),
  (51, 'Pumpkin Pie', 'pie', 'medium', 30, 48, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"sugar","amount":99,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"all-purpose flour","amount":8,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground ginger","amount":2,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"ground nutmeg","amount":1.2,"unit":"g"},{"name":"ground cloves","amount":0.3,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"pumpkin purée","amount":425,"unit":"g"},{"name":"light cream or evaporated milk","amount":283,"unit":"g"},{"name":"single 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"}]'::jsonb, array['Heat the oven to 200°C.', 'Whisk the sugars, flour, salt and spices in a large bowl.', 'Beat the eggs, pumpkin and cream together, then whisk into the dry mix. For deeper flavour, cover and chill overnight.', 'Roll the crust to a 33 cm round, fit it into a greased 23 cm dish and crimp above the rim. Chill while the oven heats.', 'Set the dish on a baking tray and pour in the filling.', 'Bake 45 to 50 minutes until the edges are set 5 cm in and the centre still wobbles.', 'Cool on a rack. The centre finishes setting as it rests. Refrigerate leftovers.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/pumpkin-pie-recipe"}'::jsonb, false, null),
  (52, 'Key Lime Pie', 'pie', 'easy', 20, 25, 9, 'round-23', null, array['vegetarian']::text[], '[{"name":"graham cracker crumbs","amount":150,"unit":"g"},{"name":"light brown sugar","amount":70,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"sweetened condensed milk","amount":794,"unit":"g"},{"name":"plain Greek yogurt","amount":240,"unit":"g"},{"name":"lime zest","amount":6,"unit":"g"},{"name":"lime juice","amount":180,"unit":"g"},{"name":"heavy cream","amount":235,"unit":"g"},{"name":"icing sugar","amount":15,"unit":"g"},{"name":"lime zest, for the top","amount":2,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C. Mix the crumbs, brown sugar and melted butter with a fork, then your hands, until evenly damp.', 'Press into a 23 cm pie dish, sides first, then the base. Bake 10 minutes until slightly browned and set on a rack.', 'Lower the oven to 175°C. Whisk the condensed milk, yogurt, lime zest and lime juice together and pour into the warm crust.', 'Bake about 15 minutes, until almost set with a slight wobble in the centre.', 'Cool 30 minutes at room temperature, then chill about 3 hours.', 'Whip the cold cream to soft peaks, add the icing sugar and whip to medium peaks. Spread over the pie and finish with the extra zest.', 'Serve cold, wiping the knife between slices.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/key-lime-pie.html"}'::jsonb, false, null),
  (53, 'Classic Lemon Meringue Pie', 'pie', 'hard', 25, 22, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":163,"unit":"g"},{"name":"salt, for the crust","amount":2,"unit":"g"},{"name":"vegetable oil","amount":67,"unit":"g"},{"name":"cold milk","amount":43,"unit":"g"},{"name":"sugar, for the filling","amount":298,"unit":"g"},{"name":"cornstarch","amount":43,"unit":"g"},{"name":"cold water","amount":340,"unit":"g"},{"name":"egg yolks","amount":3,"unit":"count"},{"name":"butter","amount":43,"unit":"g"},{"name":"lemon zest","amount":6,"unit":"g"},{"name":"lemon juice","amount":113,"unit":"g"},{"name":"vanilla extract, for the filling","amount":2,"unit":"g"},{"name":"egg whites","amount":3,"unit":"count"},{"name":"cream of tartar","amount":1,"unit":"g"},{"name":"sugar, for the meringue","amount":67,"unit":"g"},{"name":"vanilla extract, for the meringue","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C. Mix the flour and salt, then stir in the oil and milk until a dough forms.', 'Roll to a 30 cm round between sheets of plastic or parchment, fit into a 23 cm pie dish, crimp and prick the base.', 'Bake the crust 12 to 15 minutes until just beginning to brown, then lower the oven to 200°C.', 'Cook the filling sugar, cornstarch and water over medium heat until thick and boiling. Boil 1 minute.', 'Whisk about a cup of the hot mix into the yolks, return it all to the pan and boil 1 minute until very thick.', 'Off the heat, stir in the butter, zest, lemon juice and vanilla. Pour into the crust.', 'Beat the egg whites with the cream of tartar, add the sugar gradually, and beat to stiff peaks. Beat in the vanilla.', 'Spread the meringue over the hot filling, sealing it to the crust. Bake 8 to 10 minutes until golden, then cool several hours.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-lemon-meringue-pie-recipe"}'::jsonb, false, null),
  (54, 'French Lemon Tart', 'pie', 'medium', 25, 40, 12, 'round-23', null, array['vegetarian']::text[], '[{"name":"single 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"lemon zest","amount":6,"unit":"g"},{"name":"lemon juice","amount":125,"unit":"g"},{"name":"sugar","amount":165,"unit":"g"},{"name":"butter, cubed","amount":170,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"egg yolks","amount":3,"unit":"count"}]'::jsonb, array['Roll out the crust, fit it into a 23 cm tart tin, prick the base and chill 30 minutes.', 'Heat the oven to 200°C. Line the crust with parchment, fill with baking weights and bake 20 minutes. Lift out the weights and bake 10 to 15 minutes more, until golden all over. Cool completely.', 'Lower the oven to 180°C.', 'Put the lemon zest, lemon juice, sugar, butter, eggs and yolks in a saucepan and whisk together.', 'Set over low to medium-low heat and whisk constantly for about 5 minutes, until the butter has melted and the mixture is thick enough for a dollop to sit briefly on the surface.', 'Pass through a fine sieve, pour into the tart shell and smooth the top.', 'Bake 5 minutes, until the centre is a soft custard and no longer liquid. It finishes setting as it cools. Cool fully before slicing.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/lemon-tart/"}'::jsonb, false, null),
  (55, 'Cream Puffs and Éclairs', 'pastry', 'hard', 20, 45, 12, null, null, array['vegetarian']::text[], '[{"name":"water","amount":227,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"salt","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"heavy cream, for the filling","amount":454,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"semisweet chocolate chips, for the icing","amount":170,"unit":"g"},{"name":"heavy cream, for the icing","amount":113,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C and line two trays.', 'Boil the water, butter and salt until the butter melts.', 'Off the heat, add the flour all at once and stir hard. Return to medium heat and stir until the dough smooths and pulls from the pan, under a minute.', 'Cool 5 to 10 minutes, then beat in the eggs one at a time and beat at least 2 minutes more.', 'Spoon mounds for puffs, or pipe 13 cm logs for éclairs, about 8 cm apart.', 'Bake 15 minutes at 220°C, then 25 minutes at 175°C. Slit the tops and bake 5 minutes more to release steam. Cool, then split.', 'Whip the cream with the sugar and vanilla to stiff peaks and fill the puffs. (For éclairs, use pastry cream.)', 'Melt the chocolate in the hot cream, stir smooth and spread over éclairs.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cream-puffs-and-eclairs-recipe"}'::jsonb, false, null),
  (56, 'Quiche Lorraine', 'pie', 'medium', 35, 55, 8, 'round-23', null, array[]::text[], '[{"name":"single 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"bacon, chopped","amount":170,"unit":"g"},{"name":"onion, diced","amount":227,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"heavy cream","amount":227,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"black pepper","amount":0.6,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"chives or scallion tops","amount":6,"unit":"g"},{"name":"Swiss, Gruyère or cheddar, grated","amount":113,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C and lightly grease a 23 cm pie dish.', 'Fit the pastry into the dish, crimp the edge and prick the base.', 'Line with foil or parchment, fill with weights and pre-bake 15 minutes. Cool briefly, then remove the weights. Lower the oven to 175°C.', 'Brown the bacon, drain most of the fat, then soften the onion in the pan. Set aside.', 'Heat the milk, cream, salt and pepper to just below a simmer.', 'Whisk the eggs, whisk in a little hot cream to temper them, then stir back into the pan.', 'Spread the bacon and onion in the crust, pour in the custard and top with the chives and cheese.', 'Bake on a tray 35 to 40 minutes until a knife 5 cm from the edge comes out clean and the centre is 71 to 74°C. Cool 15 minutes.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/quiche-lorraine-recipe"}'::jsonb, false, null),
  (57, 'All-Butter Pie Crust', 'pie', 'easy', 15, 0, 16, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"buttermilk powder (optional)","amount":18,"unit":"g"},{"name":"cold unsalted butter","amount":227,"unit":"g"},{"name":"ice water","amount":128,"unit":"g"}]'::jsonb, array['Whisk the flour, salt and buttermilk powder.', 'Work in the cold cubed butter, leaving pea-sized pieces.', 'Add ice water a little at a time, tossing, until the dough holds together when squeezed.', 'Divide into two disks. Chill at least 30 minutes, or roll right away.', 'If chilled longer than 30 minutes, rest 10 to 15 minutes at room temperature until it rolls easily.', 'Use in a pie recipe (this makes two single crusts or one double crust). It keeps 2 days chilled or 2 months frozen, well wrapped.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/all-butter-pie-crust-recipe"}'::jsonb, false, null),
  (58, 'Old-Fashioned Apple Crisp', 'pie', 'easy', 20, 60, 10, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"apples, peeled and cut into wedges","amount":2270,"unit":"g"},{"name":"orange zest","amount":6,"unit":"g"},{"name":"lemon zest","amount":3,"unit":"g"},{"name":"orange juice","amount":30,"unit":"g"},{"name":"lemon juice","amount":30,"unit":"g"},{"name":"sugar","amount":100,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"ground nutmeg","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":190,"unit":"g"},{"name":"sugar, for the topping","amount":150,"unit":"g"},{"name":"light brown sugar","amount":160,"unit":"g"},{"name":"kosher salt","amount":1.5,"unit":"g"},{"name":"rolled oats","amount":90,"unit":"g"},{"name":"cold butter, diced","amount":227,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and butter a baking dish of about 33 x 23 cm.', 'Peel and core the apples and cut them into large wedges. Toss with both zests, both juices, the 100 g of sugar, the cinnamon and the nutmeg, and tip into the dish.', 'Mix the flour, topping sugar, brown sugar, salt, oats and cold butter on low speed (or rub together by hand) until crumbly, with butter pieces the size of peas.', 'Scatter the topping evenly over the apples.', 'Set the dish on a tray to catch drips and bake 1 hour, until the top is brown and the apples are bubbling. Serve warm.']::text[], '{"name":"Food Network","url":"https://www.foodnetwork.com/recipes/ina-garten/old-fashioned-apple-crisp-recipe-1941803"}'::jsonb, false, null),
  (59, 'Strawberry Lemonade Bars', 'bars', 'easy', 20, 30, 16, 'square-20', null, array['vegetarian']::text[], '[{"name":"sugar","amount":264,"unit":"g"},{"name":"lemon zest","amount":6,"unit":"g"},{"name":"salt, for the bars","amount":6,"unit":"g"},{"name":"vanilla extract, for the bars","amount":4,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"lemon juice","amount":28,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"baking powder","amount":2.5,"unit":"g"},{"name":"freeze-dried strawberries","amount":10,"unit":"g"},{"name":"butter, softened, for the frosting","amount":85,"unit":"g"},{"name":"salt, for the frosting","amount":0.7,"unit":"g"},{"name":"icing sugar","amount":113,"unit":"g"},{"name":"vanilla extract, for the frosting","amount":4,"unit":"g"},{"name":"milk","amount":10,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Line a 20 cm metal square tin with a parchment sling and grease lightly.', 'Combine the sugar, zest, salt and vanilla in a bowl.', 'Melt the butter with the lemon juice and pour over the sugar mix. Whisk, then beat 30 seconds until thick and glossy. Whisk in the eggs.', 'Fold in the flour and baking powder until no streaks remain.', 'Spread in the tin and bake 28 to 32 minutes until set and golden with a few moist crumbs on a skewer.', 'Cool completely in the tin, about 1 hour.', 'Crush the strawberries to a fine powder. Beat the soft butter, strawberry powder and salt, add the icing sugar, vanilla and milk and whip until fluffy.', 'Spread over the bars and slice.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/strawberry-lemonade-bars-recipe"}'::jsonb, false, null),
  (60, 'Hot Buttered Soft Pretzels', 'buns', 'medium', 20, 9, 8, null, null, array['vegetarian']::text[], '[{"name":"bread flour","amount":300,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":4,"unit":"g"},{"name":"instant yeast","amount":7,"unit":"g"},{"name":"warm water","amount":212,"unit":"g"},{"name":"baking soda, for the bath","amount":28,"unit":"g"},{"name":"coarse pretzel salt","amount":3,"unit":"g"},{"name":"butter, melted","amount":43,"unit":"g"}]'::jsonb, array['Mix the flour, salt, sugar, yeast and warm water and knead 5 to 8 minutes by hand or mixer.', 'Put in a greased bowl, cover and rise 30 minutes.', 'Dissolve the baking soda in 227 g of boiling water and let it cool to lukewarm. Heat the oven to 245°C and prepare a tray.', 'Divide the dough into 8 pieces of about 70 g and rest uncovered 5 minutes.', 'Roll each into a 70 cm rope and twist into a pretzel.', 'Dip them in the soda bath four at a time for 2 minutes each, set them on the tray, salt lightly and rest 10 minutes.', 'Bake 8 to 9 minutes until golden.', 'Brush the warm pretzels generously with melted butter.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/hot-buttered-soft-pretzels-recipe"}'::jsonb, false, null),
  (61, 'Rugelach', 'pastry', 'medium', 45, 28, 48, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":325,"unit":"g"},{"name":"salt","amount":2,"unit":"g"},{"name":"cold butter, cubed","amount":226,"unit":"g"},{"name":"cold cream cheese, cubed","amount":227,"unit":"g"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"light brown sugar","amount":105,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"walnuts","amount":115,"unit":"g"},{"name":"raisins","amount":75,"unit":"g"},{"name":"ground cinnamon","amount":10,"unit":"g"}]'::jsonb, array['Pulse the flour and salt in a food processor. Add the cold butter, cream cheese and egg yolk and pulse until crumbly, with lumps the size of peas.', 'Tip out, knead briefly until it holds together and divide into 4 equal pieces. Flatten each into a disc, wrap and chill at least 1 hour.', 'Wipe out the processor and pulse both sugars, the walnuts, raisins and cinnamon until the nuts and raisins are finely chopped.', 'Heat the oven to 175°C and line two trays with parchment.', 'On a lightly floured surface, roll one disc into a 28 cm circle about 3 mm thick. Scatter a quarter of the filling over it and press it into the dough.', 'Cut into 12 wedges. Roll each one up from the wide end to the point and set it point side down on a tray, 2.5 cm apart. Repeat with the other discs.', 'Bake 25 to 30 minutes, swapping and turning the trays halfway, until the tops are lightly golden and the bottoms crisp. Cool on a rack.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/rugelach.html"}'::jsonb, false, null),
  (62, 'Lattice-Top Apple Pie', 'pie', 'hard', 45, 60, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"double 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"butter","amount":113,"unit":"g"},{"name":"all-purpose flour","amount":25,"unit":"g"},{"name":"water","amount":60,"unit":"g"},{"name":"sugar","amount":200,"unit":"g"},{"name":"Granny Smith apples","amount":1020,"unit":"g"},{"name":"ground cinnamon","amount":4,"unit":"g"},{"name":"egg, for glazing","amount":1,"unit":"count"},{"name":"water, for glazing","amount":15,"unit":"g"}]'::jsonb, array['Make the pie crust and chill it. Heat the oven to 220°C.', 'Melt the butter over medium heat, whisk in the flour and simmer 1 minute, whisking all the time. Whisk in the 60 g of water, then the sugar. Simmer gently for 3 minutes, stirring often, until thick but still pourable. Take off the heat.', 'Peel and core the apples and slice them about 6 mm thick. Toss with the cinnamon, pour the sauce over and stir to coat.', 'Roll half the crust into a 30 cm round and fit it into a deep 23 cm pie dish. Pile in the apples, slightly higher in the middle.', 'Roll the rest of the crust into a 28 cm round, cut it into 10 strips and weave them into a lattice over the apples. Trim and crimp the edge.', 'Beat the egg with the 15 g of water and brush it over the lattice.', 'Bake 15 minutes, lower the oven to 175°C and bake 45 minutes more, until the apples are tender and the filling has been bubbling for at least 5 minutes.', 'Rest 2 to 3 hours at room temperature before slicing, so the filling can set.']::text[], '{"name":"Natasha''s Kitchen","url":"https://natashaskitchen.com/apple-pie-recipe/"}'::jsonb, false, null),
  (63, 'Carrot Sheet Cake with Cream Cheese Frosting', 'cake', 'medium', 30, 45, 20, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"dried currants","amount":70,"unit":"g"},{"name":"all-purpose flour","amount":295,"unit":"g"},{"name":"baking soda","amount":12,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ground cinnamon","amount":4,"unit":"g"},{"name":"ground nutmeg","amount":0.5,"unit":"g"},{"name":"ground allspice","amount":0.5,"unit":"g"},{"name":"ground cloves","amount":0.5,"unit":"g"},{"name":"pecans or walnuts, chopped","amount":85,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"sugar","amount":300,"unit":"g"},{"name":"dark brown sugar","amount":105,"unit":"g"},{"name":"vegetable oil","amount":250,"unit":"g"},{"name":"carrots, finely grated","amount":275,"unit":"g"},{"name":"cream cheese","amount":227,"unit":"g"},{"name":"butter, for the frosting","amount":113,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt, for the frosting","amount":0.5,"unit":"g"},{"name":"icing sugar","amount":460,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Grease a 33 x 23 cm tin and line the base with parchment.', 'Cover the currants with hot tap water, leave 15 minutes, then drain.', 'Whisk the flour, baking soda, salt and spices. Toss about 30 g of this mix with the drained currants and the chopped nuts so they do not sink.', 'Whisk the eggs with both sugars, then whisk in the oil.', 'Add the rest of the flour mix, the grated carrots and the coated nuts and currants. Stir with a spatula until evenly mixed.', 'Spread in the tin and bake about 45 minutes, until a skewer in the centre comes out clean. Cool 30 minutes in the tin, turn out and cool completely.', 'Beat the cream cheese, soft butter, vanilla and salt until smooth and light. Add the icing sugar a little at a time on low speed, then beat about 1 minute until fluffy.', 'Spread the frosting over the cold cake. Keep it in the fridge and bring to room temperature before serving.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/carrot-cake.html"}'::jsonb, false, null),
  (64, 'Sour Cream Coffee Cake', 'cake', 'easy', 15, 35, 12, 'square-23', null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":1.5,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"sour cream or plain yogurt","amount":227,"unit":"g"},{"name":"sugar, for the filling","amount":99,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"chopped walnuts or pecans (optional)","amount":57,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease and flour a 23 cm square tin.', 'Beat the butter, sugar and eggs until combined.', 'Whisk the flour, baking powder, baking soda and salt in another bowl.', 'Add the dry mix and the sour cream to the butter mixture in alternating portions, mixing after each.', 'Stir the filling sugar, cinnamon, vanilla and nuts together until crumbly.', 'Spread half the batter in the tin, sprinkle with half the filling, then repeat.', 'Bake 30 to 40 minutes until a skewer shows only a few moist crumbs. Serve warm or at room temperature.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/our-favorite-sour-cream-coffee-cake-recipe"}'::jsonb, false, null),
  (65, 'New York Cheesecake', 'cake', 'hard', 30, 110, 10, 'round-23', null, array['vegetarian']::text[], '[{"name":"graham cracker crumbs","amount":150,"unit":"g"},{"name":"butter, melted","amount":70,"unit":"g"},{"name":"sugar, for the crust","amount":25,"unit":"g"},{"name":"salt, for the crust","amount":0.8,"unit":"g"},{"name":"cream cheese","amount":907,"unit":"g"},{"name":"sugar","amount":400,"unit":"g"},{"name":"all-purpose flour","amount":25,"unit":"g"},{"name":"vanilla extract","amount":17,"unit":"g"},{"name":"lemon zest","amount":2,"unit":"g"},{"name":"lemon juice","amount":10,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"eggs","amount":6,"unit":"count"},{"name":"sour cream","amount":120,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C with a rack in the lower middle. Wrap the outside of a 23 cm springform tin in two layers of wide heavy foil and grease the inside.', 'Mix the crumbs, melted butter, 25 g of sugar and the pinch of salt and press evenly over the base. Bake 10 minutes until set.', 'Lower the oven to 165°C and boil a kettle of water.', 'Beat the cream cheese, sugar and flour on medium speed for about 1 minute, just until smooth. Beat in the vanilla, lemon zest, lemon juice and salt on low.', 'Add the eggs one at a time on low, scraping the bowl, then mix in the sour cream. Stop as soon as it is even.', 'Set the tin in a large roasting pan and pour the batter over the crust. Pour boiling water into the roasting pan to come about 2.5 cm up the sides of the tin.', 'Bake 1.5 to 1.75 hours, until just set with a slight wobble. Cover loosely with foil if the top browns too much.', 'Leave in the water bath for about 45 minutes until the water is just warm. Lift out, remove the foil and chill, covered, for at least 8 hours before unmoulding.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/new-york-style-cheesecake.html"}'::jsonb, false, null),
  (66, 'Vanilla Layer Cake with Buttercream', 'cake', 'medium', 30, 30, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"baking powder","amount":10,"unit":"g"},{"name":"salt","amount":1,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"caster sugar","amount":330,"unit":"g"},{"name":"whole milk","amount":255,"unit":"g"},{"name":"butter, cubed","amount":115,"unit":"g"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"vegetable oil","amount":13,"unit":"g"},{"name":"butter, softened, for the buttercream","amount":225,"unit":"g"},{"name":"icing sugar","amount":500,"unit":"g"},{"name":"vanilla extract, for the buttercream","amount":13,"unit":"g"},{"name":"milk, for the buttercream","amount":40,"unit":"g"}]'::jsonb, array['Heat the oven to 180°C. Grease two 20 cm round tins and line the bases with parchment.', 'Whisk the flour, baking powder and salt.', 'Beat the eggs for 30 seconds, then pour in the sugar while beating. Keep beating on high for 7 minutes, until tripled in volume and almost white.', 'Meanwhile heat the milk and cubed butter until the butter melts and the milk is hot.', 'Add the flour mixture to the eggs in three goes, mixing on the lowest speed for a few seconds each time, just until no flour shows.', 'Stir the vanilla and oil into the hot milk. Whisk in two ladles of the batter until smooth, then pour this back into the main batter with the mixer on low. Mix about 10 seconds, until smooth and pourable.', 'Divide between the tins and knock each on the counter three times to pop large bubbles. Bake 30 minutes, until golden and a skewer comes out clean.', 'Cool 15 minutes in the tins, then turn out upside down onto racks and cool completely.', 'Beat the soft butter for 3 minutes until pale. Add the icing sugar in three parts on low, beat 3 minutes on high, then beat in the vanilla and just enough milk for a soft, spreadable buttercream. Fill and frost the cold cakes.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/my-very-best-vanilla-cake/"}'::jsonb, false, null),
  (67, 'Beatty''s Chocolate Cake', 'cake', 'medium', 30, 38, 10, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":220,"unit":"g"},{"name":"sugar","amount":400,"unit":"g"},{"name":"cocoa powder","amount":65,"unit":"g"},{"name":"baking soda","amount":12,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"kosher salt","amount":3,"unit":"g"},{"name":"buttermilk","amount":240,"unit":"g"},{"name":"vegetable oil","amount":100,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"hot brewed coffee","amount":235,"unit":"g"},{"name":"semisweet chocolate, chopped","amount":170,"unit":"g"},{"name":"butter, for the frosting","amount":227,"unit":"g"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"vanilla extract, for the frosting","amount":4,"unit":"g"},{"name":"icing sugar, sifted","amount":145,"unit":"g"},{"name":"instant coffee powder","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Butter two 20 cm round tins, line the bases with parchment, then butter and flour them.', 'Mix the flour, sugar, cocoa, baking soda, baking powder and salt on low speed.', 'Stir the buttermilk, oil, eggs and vanilla together in another bowl, then add slowly to the dry ingredients with the mixer on low.', 'Pour in the hot coffee and stir just until combined, scraping the bottom of the bowl. The batter is thin.', 'Divide between the tins and bake 35 to 40 minutes, until a skewer comes out clean. Cool 30 minutes in the tins, then turn out and cool completely.', 'For the frosting, melt the chocolate in a bowl over simmering water and let it cool to room temperature.', 'Beat the soft butter for about 3 minutes until pale and fluffy, then beat in the egg yolk and vanilla for 3 minutes more. Add the icing sugar gradually on low and beat until smooth.', 'Dissolve the coffee powder in 2 teaspoons of very hot water. Mix it and the cooled chocolate into the butter on low, just until blended.', 'Sandwich the two cakes with frosting, then cover the top and sides. Use the frosting straight away, before it firms up.']::text[], '{"name":"Food Network","url":"https://www.foodnetwork.com/recipes/ina-garten/beattys-chocolate-cake-recipe-1947521"}'::jsonb, false, null),
  (68, 'Chocolate Guinness Cake', 'cake', 'easy', 20, 50, 12, 'round-23', null, array['vegetarian']::text[], '[{"name":"Guinness","amount":250,"unit":"g"},{"name":"butter","amount":250,"unit":"g"},{"name":"cocoa powder","amount":75,"unit":"g"},{"name":"caster sugar","amount":400,"unit":"g"},{"name":"sour cream","amount":150,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":11,"unit":"g"},{"name":"all-purpose flour","amount":275,"unit":"g"},{"name":"baking soda","amount":15,"unit":"g"},{"name":"cream cheese","amount":300,"unit":"g"},{"name":"icing sugar","amount":150,"unit":"g"},{"name":"cornstarch","amount":5,"unit":"g"},{"name":"heavy cream","amount":125,"unit":"g"}]'::jsonb, array['Heat the oven to 180°C. Butter a 23 cm springform tin and line it.', 'Warm the Guinness and butter in a large, wide saucepan until the butter melts. Take off the heat and whisk in the cocoa and sugar.', 'Beat the sour cream with the eggs and vanilla, pour into the pan and whisk, then whisk in the flour and baking soda.', 'Pour the batter into the tin and bake 45 minutes to 1 hour, until risen and a skewer in the centre comes out clean. Cool completely in the tin on a rack.', 'Whip the cream cheese until smooth, sift in the icing sugar and cornstarch and beat to combine.', 'Add the cream and beat until the topping is thick enough to spread.', 'Unmould the cold cake and spread the topping over the top only, leaving the sides bare.']::text[], '{"name":"Nigella Lawson","url":"https://www.nigella.com/recipes/chocolate-guinness-cake"}'::jsonb, false, null),
  (69, 'Maple Pudding Cake (Pouding Chômeur)', 'cake', 'easy', 15, 25, 8, 'square-20', null, array['vegetarian']::text[], '[{"name":"heavy cream","amount":310,"unit":"g"},{"name":"maple syrup","amount":330,"unit":"g"},{"name":"light brown sugar","amount":55,"unit":"g"},{"name":"all-purpose flour","amount":115,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"salt","amount":0.8,"unit":"g"},{"name":"sugar","amount":85,"unit":"g"},{"name":"vegetable oil","amount":55,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"milk","amount":90,"unit":"g"}]'::jsonb, array['Heat the oven to 180°C with a rack in the middle.', 'For the sauce, whisk the cream, maple syrup and brown sugar in a small pot and bring to the boil. Simmer over medium heat for 5 minutes and take off the heat.', 'Mix the flour, baking powder and salt in a bowl.', 'In another bowl beat the sugar, oil, vanilla and egg with an electric mixer.', 'On low speed add the flour mixture in parts, alternating with the milk.', 'Spread the batter in a 20 cm square dish, then slowly pour the hot sauce over it. The cake rises through the sauce as it bakes.', 'Bake 25 minutes, until a skewer in the centre of the cake comes out clean. Cool on a rack and serve warm.']::text[], '{"name":"Ricardo","url":"https://www.ricardocuisine.com/en/recipes/8894-maple-pudding-cake-pouding-chomeur"}'::jsonb, false, null),
  (70, 'Cinnamon Roll Cake', 'cake', 'easy', 25, 33, 8, 'round-20', null, array['vegetarian']::text[], '[{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"butter, softened, for the topping","amount":42,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"all-purpose flour","amount":160,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"plain whole-milk yogurt (not Greek)","amount":151,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"icing sugar","amount":113,"unit":"g"},{"name":"cream cheese","amount":85,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Line a 20 cm round tin with parchment and grease the parchment and sides.', 'Mix the brown sugar, soft butter and cinnamon until smooth and slightly fluffy.', 'Whisk the flour, sugar, baking powder and salt.', 'Whisk in the yogurt, melted butter, egg and vanilla until mostly smooth. Small lumps are fine.', 'Spread the batter in the tin, dollop on the cinnamon topping (keep 1 to 2 teaspoons back) and swirl with a knife.', 'Bake 30 to 35 minutes until a skewer in the centre comes out clean. Cool 20 minutes in the tin.', 'Beat the icing sugar and cream cheese smooth, spread over the cake, drizzle with the reserved topping and swirl.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cinnamon-roll-cake-recipe"}'::jsonb, false, null),
  (71, 'Double Chocolate Chip Cookies', 'cookies', 'easy', 15, 7, 13, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"light brown sugar","amount":200,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":143,"unit":"g"},{"name":"natural cocoa powder","amount":57,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"instant espresso powder (optional)","amount":1,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"milk chocolate chips","amount":85,"unit":"g"},{"name":"semisweet chocolate chips","amount":85,"unit":"g"},{"name":"flaky sea salt (optional)","amount":1,"unit":"g"}]'::jsonb, array['Melt the butter, whisk in the brown sugar and let it cool until just warm.', 'Whisk in the egg, yolk and vanilla until smooth.', 'Stir in the flour, cocoa, baking soda, espresso powder and salt with a spatula, then fold in both kinds of chocolate chips. The dough is sticky and firms up as it rests.', 'Scoop 60 g balls onto a parchment-lined tray and roll them smooth. Cover and chill at least 1 hour, or up to 2 days.', 'Heat the oven to 200°C.', 'Bake about 7 minutes, until just set. Sprinkle with flaky salt straight away if using.', 'Cool 5 minutes on the tray, then move to a rack.']::text[], '{"name":"Handle the Heat","url":"https://handletheheat.com/double-chocolate-cookies/"}'::jsonb, false, null),
  (72, 'White Chocolate Macadamia Cookies', 'cookies', 'easy', 20, 12, 28, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":381,"unit":"g"},{"name":"cornstarch","amount":5,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"butter","amount":226,"unit":"g"},{"name":"light brown sugar","amount":200,"unit":"g"},{"name":"sugar","amount":100,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"vanilla extract","amount":9,"unit":"g"},{"name":"white chocolate chips","amount":255,"unit":"g"},{"name":"macadamia nuts, chopped","amount":210,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line trays with parchment.', 'Whisk the flour, cornstarch, baking soda, baking powder and salt.', 'Beat the butter with both sugars on medium-high for 2 to 3 minutes until light and fluffy.', 'Beat in the eggs and the yolk one at a time, then the vanilla.', 'Mix in the flour mixture on low, then fold in the white chocolate chips and macadamias with a spatula.', 'For deeper flavour, wrap and chill the dough for 1 to 3 days, then let it soften just enough to scoop. This step is optional.', 'Scoop mounds of about 3 tablespoons, at least 6 cm apart. Bake 11 to 12 minutes until golden brown.', 'Cool 5 minutes on the tray, then on a rack.']::text[], '{"name":"Handle the Heat","url":"https://handletheheat.com/white-chocolate-macadamia-nut-cookies/"}'::jsonb, false, null),
  (73, 'Lemon Cookies', 'cookies', 'easy', 20, 12, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":280,"unit":"g"},{"name":"cornmeal","amount":35,"unit":"g"},{"name":"poppy seeds","amount":18,"unit":"g"},{"name":"baking soda","amount":3,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":200,"unit":"g"},{"name":"lemon zest","amount":3,"unit":"g"},{"name":"orange zest","amount":3,"unit":"g"},{"name":"extra-virgin olive oil","amount":55,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"lemon juice","amount":30,"unit":"g"},{"name":"sugar, for sprinkling","amount":15,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line a tray with parchment.', 'Whisk the flour, cornmeal, poppy seeds, baking soda and salt.', 'Beat the soft butter with the sugar and both zests on medium speed until well combined.', 'Add the olive oil, egg and lemon juice and beat about 1 minute, scraping the bowl, until pale and even.', 'Mix in the dry ingredients on low until just combined. The dough is fairly dense.', 'Scoop 12 large mounds of about 60 ml each, leaving room to spread, and sprinkle the tops with sugar.', 'Bake 12 minutes. They will still look underdone: take them out anyway.', 'Leave 1 minute on the tray, then cool completely on a rack.']::text[], '{"name":"Love and Lemons","url":"https://www.loveandlemons.com/lemon-cookies/"}'::jsonb, false, null),
  (74, 'Chewy Molasses Cookies', 'cookies', 'easy', 15, 10, 16, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"dark brown sugar","amount":70,"unit":"g"},{"name":"sugar","amount":65,"unit":"g"},{"name":"molasses","amount":115,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":250,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"ground ginger","amount":2,"unit":"g"},{"name":"ground cardamom","amount":1,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"water","amount":15,"unit":"g"},{"name":"sugar, for rolling","amount":65,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line a large tray with parchment.', 'Beat the soft butter with the brown sugar and sugar until creamy, then mix in the molasses and vanilla.', 'Stir the flour, cinnamon, baking soda, ginger, cardamom and salt together and add to the butter mixture a little at a time.', 'Mix in the water. If the dough still seems dry, add a little more.', 'Scoop the dough into 16 balls and roll them in the extra sugar.', 'Set 5 cm apart on the tray and press the tops down slightly.', 'Bake 10 minutes, until puffed and cracked on top. Cool 10 minutes on the tray, then on a rack.']::text[], '{"name":"Love and Lemons","url":"https://www.loveandlemons.com/molasses-cookies/"}'::jsonb, false, null),
  (75, 'Homemade Pita Bread', 'flatbread', 'medium', 30, 8, 12, null, null, array['vegetarian']::text[], '[{"name":"warm water","amount":177,"unit":"g"},{"name":"active dry yeast","amount":7,"unit":"g"},{"name":"sugar","amount":17,"unit":"g"},{"name":"bread flour","amount":469,"unit":"g"},{"name":"salt","amount":9,"unit":"g"},{"name":"extra-virgin olive oil","amount":40,"unit":"g"},{"name":"whole-milk Greek yogurt","amount":180,"unit":"g"}]'::jsonb, array['Stir the warm water, yeast and a teaspoon of the sugar together and leave about 5 minutes until foamy.', 'Mix the flour, salt and the rest of the sugar in a large bowl. Add the yeast mixture, olive oil and yogurt and mix to a dough.', 'Knead 7 to 10 minutes, by machine or by hand, until soft and only slightly sticky. Add a little flour if needed.', 'Put in an oiled bowl, cover and rise about 2 hours until doubled.', 'Heat the oven to 260°C and line two trays with parchment.', 'Divide the dough into 12 balls, cover and rest 20 minutes.', 'Roll each ball into a round between 0.5 and 1 cm thick and space them 2.5 cm apart on the trays.', 'Bake one tray at a time for about 8 minutes, until puffed and lightly browned, turning the tray after 5 minutes if they puff unevenly. Cool on a rack.']::text[], '{"name":"Love and Lemons","url":"https://www.loveandlemons.com/pita-bread/"}'::jsonb, false, null),
  (76, 'Ranger Cookies', 'cookies', 'easy', 15, 11, 60, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":226,"unit":"g"},{"name":"light brown sugar","amount":213,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":2.5,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"rolled oats","amount":89,"unit":"g"},{"name":"sweetened shredded coconut","amount":85,"unit":"g"},{"name":"chocolate chips","amount":170,"unit":"g"},{"name":"crispy rice cereal","amount":67,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease or line the trays.', 'Cream the butter, both sugars, vanilla and salt until fluffy, then beat in the eggs.', 'Whisk the flour, baking powder and baking soda and mix into the wet ingredients.', 'Fold in the oats, coconut, chocolate chips and cereal until just combined.', 'Drop rounded teaspoons onto the trays, spaced apart.', 'Bake 10 to 12 minutes until golden brown. Cool on the tray or a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/ranger-cookies-recipe"}'::jsonb, false, null),
  (77, 'Bara Brith (Welsh Tea Loaf)', 'quick bread', 'easy', 15, 45, 10, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"boiling water","amount":300,"unit":"g"},{"name":"black tea bags","amount":2,"unit":"count"},{"name":"currants","amount":50,"unit":"g"},{"name":"mixed dried fruit","amount":400,"unit":"g"},{"name":"dark brown sugar","amount":100,"unit":"g"},{"name":"mixed spice","amount":4,"unit":"g"},{"name":"self-raising flour","amount":250,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"honey, for glazing","amount":21,"unit":"g"}]'::jsonb, array['Pour the boiling water over the tea bags and brew for 5 minutes.', 'Put the currants, mixed fruit and sugar in a large bowl. Pour in the hot tea, squeezing out the bags, add the mixed spice and stir until the sugar dissolves. Cover and soak overnight, or at least 6 hours.', 'Heat the oven to 180°C. Butter a 23 x 13 cm loaf tin and line the base.', 'Stir the flour and salt into the soaked fruit and its liquid. Beat the egg, add it and mix until no pockets of flour are left.', 'Spoon into the tin, level the top and bake 40 to 50 minutes, until firm, dark gold and a skewer comes out clean.', 'Brush the hot loaf with the honey and let it cool completely in the tin.', 'Wrap well and, if you can wait, keep it two days before slicing. Serve thickly buttered.']::text[], '{"name":"Nigella Lawson","url":"https://www.nigella.com/recipes/bara-brith"}'::jsonb, false, null),
  (78, 'Pistachio Baklava', 'pastry', 'medium', 40, 30, 16, 'square-23', null, array['vegetarian']::text[], '[{"name":"water","amount":300,"unit":"g"},{"name":"sugar","amount":500,"unit":"g"},{"name":"lemon juice","amount":15,"unit":"g"},{"name":"rosewater","amount":15,"unit":"g"},{"name":"orange-flower water","amount":15,"unit":"g"},{"name":"butter, melted","amount":125,"unit":"g"},{"name":"filo pastry","amount":400,"unit":"g"},{"name":"pistachios, finely chopped","amount":325,"unit":"g"}]'::jsonb, array['Make the syrup first so it has time to chill. Boil the water, sugar and lemon juice for 5 minutes, take off the heat and stir in the rosewater and orange-flower water. Cool, then refrigerate.', 'Heat the oven to 180°C and brush a 23 cm square tin with melted butter.', 'Layer half the filo into the tin, brushing each sheet with butter and letting the edges hang over the sides.', 'Spread the pistachios evenly over the filo.', 'Cover with the rest of the filo, buttering each sheet as before. Butter the top sheet well and trim the edges level with the tin.', 'With a sharp knife cut parallel lines 4 to 5 cm apart, then cut across them at an angle to make diamonds. Cut right through to the base.', 'Bake 30 minutes, until puffed and golden brown.', 'Pour half the cold syrup over the hot baklava straight away. Let it soak in for a few minutes, then pour over the rest. Cool in the tin.']::text[], '{"name":"Nigella Lawson","url":"https://www.nigella.com/recipes/baklava"}'::jsonb, false, null),
  (79, 'Oat and Seed Breakfast Bars', 'bars', 'easy', 10, 60, 16, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"sweetened condensed milk","amount":397,"unit":"g"},{"name":"rolled oats","amount":250,"unit":"g"},{"name":"shredded coconut","amount":75,"unit":"g"},{"name":"dried cranberries","amount":100,"unit":"g"},{"name":"mixed seeds (pumpkin, sunflower, sesame)","amount":125,"unit":"g"},{"name":"unsalted peanuts","amount":125,"unit":"g"}]'::jsonb, array['Heat the oven to 130°C and oil a 33 x 23 cm tin.', 'Warm the condensed milk in a large pan.', 'Mix the oats, coconut, cranberries, seeds and peanuts together, add to the warm condensed milk and fold until everything is coated.', 'Tip into the tin and press down firmly and evenly with a spatula or damp hands.', 'Bake 1 hour.', 'Leave about 15 minutes, then cut four across and four down to make 16 bars. Cool completely in the tin.']::text[], '{"name":"Nigella Lawson","url":"https://www.nigella.com/recipes/breakfast-bars"}'::jsonb, false, null),
  (80, 'Japanese Milk Bread', 'bread', 'medium', 30, 33, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"water, for the tangzhong","amount":43,"unit":"g"},{"name":"milk, for the tangzhong","amount":43,"unit":"g"},{"name":"bread flour, for the tangzhong","amount":14,"unit":"g"},{"name":"bread flour","amount":300,"unit":"g"},{"name":"dry milk powder","amount":14,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"milk","amount":113,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"butter, melted","amount":57,"unit":"g"}]'::jsonb, array['Whisk the tangzhong water, milk and flour in a pan and cook over low heat, 3 to 5 minutes, until thick and the whisk leaves lines. Cool to lukewarm.', 'Mix the tangzhong with the dough ingredients and knead until smooth and elastic, about 15 minutes in a mixer.', 'Rest in a greased covered bowl 1 to 1.5 hours until puffy.', 'Divide into four pieces of about 172 g, then fold and roll each into a 10 cm log.', 'Set the logs seam-side down in a greased 23 cm tin and rise 40 to 50 minutes until puffy. Heat the oven to 175°C near the end.', 'Brush with milk and bake 30 to 35 minutes until golden and at least 88°C inside.', 'Cool in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/japanese-milk-bread-recipe"}'::jsonb, false, null),
  (81, 'Chocolate Babka', 'bread', 'hard', 45, 48, 10, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":329,"unit":"g"},{"name":"sugar","amount":36,"unit":"g"},{"name":"instant yeast","amount":4.5,"unit":"g"},{"name":"kosher salt","amount":4,"unit":"g"},{"name":"water","amount":60,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"whole milk","amount":60,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"dark chocolate, chopped, for the filling","amount":64,"unit":"g"},{"name":"butter, for the filling","amount":42,"unit":"g"},{"name":"icing sugar","amount":30,"unit":"g"},{"name":"Dutch-process cocoa","amount":15,"unit":"g"},{"name":"salt, for the filling","amount":1.5,"unit":"g"},{"name":"dark chocolate, chopped, for sprinkling","amount":50,"unit":"g"},{"name":"sugar, for the glaze","amount":18,"unit":"g"},{"name":"water, for the glaze","amount":15,"unit":"g"}]'::jsonb, array['Whisk about 125 g of the flour with the sugar, yeast and salt in a mixer bowl.', 'Warm the water, butter, milk and vanilla to 49 to 54°C and beat into the flour mixture. Beat in one of the eggs, then the rest of the flour.', 'Knead with the dough hook until soft and slightly sticky, adding a little flour only if needed. Cover and rise 30 to 45 minutes until doubled, then chill at least 1 hour or overnight.', 'For the filling, melt the 64 g of chocolate with the filling butter and stir in the icing sugar, cocoa and salt until smooth.', 'Roll the cold dough into a 33 x 25 cm rectangle. Spread with the filling, scatter over the remaining chopped chocolate and roll up from a long side.', 'Cut the roll in half lengthways. Lay the halves cut side up in an X, twist them around each other and tuck the twist into a greased 21 x 11 cm loaf tin.', 'Cover and rise 30 minutes to 1 hour until puffed. Heat the oven to 175°C.', 'Beat the second egg with a spoonful of water, brush it over the loaf and bake 45 to 50 minutes, until golden and 88°C in the centre.', 'Dissolve the glaze sugar in the glaze water over low heat and brush over the hot loaf. Cool 10 minutes in the tin, then completely on a rack.']::text[], '{"name":"Bake from Scratch","url":"https://bakefromscratch.com/chocolate-babka/"}'::jsonb, false, null),
  (82, '100% Whole Wheat Sandwich Bread', 'bread', 'medium', 15, 38, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"lukewarm water","amount":301,"unit":"g"},{"name":"olive oil","amount":35,"unit":"g"},{"name":"honey","amount":106,"unit":"g"},{"name":"whole wheat flour","amount":454,"unit":"g"},{"name":"sunflower seeds, chopped","amount":35,"unit":"g"},{"name":"walnuts, chopped","amount":28,"unit":"g"},{"name":"salt","amount":9,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"}]'::jsonb, array['Mix everything into a shaggy dough.', 'Rest covered 20 minutes, then knead until fairly smooth.', 'Rise covered 1 to 2 hours until puffy and nearly doubled. Heat the oven to 175°C near the end.', 'Deflate gently, shape into a log and place in a lightly greased 23 cm tin.', 'Cover and rise 1 to 2 hours until domed 2.5 to 5 cm over the rim.', 'Bake 40 to 45 minutes, tenting with foil for the last 20, until golden and 90 to 96°C inside.', 'Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/king-arthurs-100-whole-wheat-sandwich-bread-recipe"}'::jsonb, false, null),
  (83, 'Braided Brioche Loaf', 'bread', 'hard', 45, 35, 10, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":8,"unit":"g"},{"name":"caster sugar","amount":45,"unit":"g"},{"name":"warm milk","amount":60,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"salt","amount":5,"unit":"g"},{"name":"butter, softened","amount":150,"unit":"g"}]'::jsonb, array['Stir the yeast and a teaspoon of the sugar into the warm milk, cover and leave 10 minutes until foamy.', 'Whisk the 3 eggs together and set about 2 tablespoons aside for glazing later.', 'Put the flour, the rest of the eggs, the salt, the remaining sugar and the yeast mixture in a stand mixer with a dough hook. Mix on the lowest speed for 5 minutes, then one speed higher for 10 minutes. The dough is sticky and paste-like.', 'Still mixing, add the soft butter a piece at a time over about 2 minutes. Keep mixing for around 20 minutes, scraping the bowl now and then, until the dough pulls away from the sides and a small piece stretches thin without tearing.', 'Shape into a ball, cover and rise somewhere warm for about 2 hours until doubled.', 'Punch down and divide into 3 equal pieces. Chilling them for 1.5 hours makes them much easier to shape.', 'Roll each piece into a 35 cm rope, braid the three together, tuck the ends under and place in a greased 21 x 11 cm loaf tin. Cover and rise about 3 hours, until a little more than doubled.', 'Heat the oven to 200°C with a rack in the lowest third. Brush the loaf gently with the reserved egg.', 'Bake 15 minutes until deep golden, cover loosely with foil and bake 20 minutes more, until 88°C in the centre. Turn out and cool at least 45 minutes before slicing.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/brioche/"}'::jsonb, false, null),
  (84, 'No-Yeast Irish Soda Bread', 'bread', 'easy', 10, 40, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"whole wheat flour","amount":260,"unit":"g"},{"name":"baking soda","amount":9,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"cold buttermilk","amount":515,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C and line a tray with parchment.', 'Whisk both flours, the baking soda and the salt in a bowl.', 'Pour in the buttermilk and stir until the dough is too stiff to stir. Work quickly from here: the baking soda starts reacting as soon as it meets the buttermilk.', 'Scrape onto a well-floured surface, dust the top with flour and knead gently no more than 8 times, just to bring it into a ball.', 'Move to the tray, pat into a disc 2.5 cm thick and cut a cross 1 cm deep in the top with a serrated knife.', 'Bake 20 minutes, lower the oven to 200°C and bake 20 minutes more, until the base sounds hollow when tapped.', 'Cool on a rack for at least 30 minutes before slicing.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/no-yeast-bread-irish-soda-bread/"}'::jsonb, false, null),
  (85, 'Overnight Bagels', 'buns', 'hard', 60, 16, 8, null, null, array['vegetarian']::text[], '[{"name":"maple syrup","amount":20,"unit":"g"},{"name":"active dry yeast","amount":7,"unit":"g"},{"name":"warm water","amount":296,"unit":"g"},{"name":"bread flour","amount":540,"unit":"g"},{"name":"salt","amount":12,"unit":"g"},{"name":"maple syrup, for the poaching water","amount":30,"unit":"g"},{"name":"baking soda, for the poaching water","amount":12,"unit":"g"},{"name":"salt, for the poaching water","amount":9,"unit":"g"},{"name":"everything bagel seasoning","amount":20,"unit":"g"}]'::jsonb, array['Stir the maple syrup and yeast into the warm water and leave about 5 minutes until foamy.', 'Put the flour, salt and yeast mixture in a mixer with a dough hook and mix on medium-low for 5 to 7 minutes, until the dough gathers around the hook. It is a stiff dough: add a spoonful of water only if it will not come together.', 'Knead by hand for 2 to 3 minutes until smooth and barely tacky. Cover and rise in a warm place for 60 to 90 minutes.', 'Divide into 8 pieces and roll each into a ball. Roll each ball into a 23 cm rope, wrap it around your hand so the ends overlap by 5 cm, and roll the join on the counter to seal it.', 'Set the bagels on two lightly oiled, parchment-lined trays, dust the tops very lightly with flour, cover and refrigerate overnight.', 'The next day, leave the bagels at room temperature for 1 hour and heat the oven to 230°C. Drop one into a bowl of water: if it floats they are ready, and if it sinks give them 30 minutes more.', 'Bring about 2 litres of water to the boil with the poaching maple syrup, baking soda and salt. Boil the bagels three at a time for 1 minute per side and return them to the trays, smooth side up.', 'Dip or sprinkle the tops with the seasoning and bake 14 to 18 minutes, until lightly golden brown.']::text[], '{"name":"Love and Lemons","url":"https://www.loveandlemons.com/bagel-recipe/"}'::jsonb, false, null),
  (86, 'Dark and Soft Dinner Rolls', 'buns', 'medium', 22, 24, 12, null, null, array['vegetarian']::text[], '[{"name":"warm water","amount":301,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"honey","amount":84,"unit":"g"},{"name":"molasses","amount":85,"unit":"g"},{"name":"bread flour","amount":330,"unit":"g"},{"name":"whole wheat flour","amount":220,"unit":"g"},{"name":"salt","amount":12,"unit":"g"},{"name":"cocoa powder (for colour)","amount":5,"unit":"g"},{"name":"instant yeast","amount":7.5,"unit":"g"},{"name":"yellow cornmeal, for coating","amount":20,"unit":"g"}]'::jsonb, array['Mix and knead all the dough ingredients in a mixer (paddle, then dough hook) or bread machine to a smooth, slightly sticky dough.', 'Rise in the bowl 60 to 90 minutes until just puffy.', 'Divide into 12 pieces of about 85 g and shape into 10 x 5 cm ovals.', 'Roll in cornmeal, set on a greased tray and rise covered 1 to 2 hours until puffy. Heat the oven to 175°C near the end.', 'Bake about 24 minutes until the bottoms are lightly browned or the centre is about 93°C.', 'Cool on a rack. Serve warm or at room temperature.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/dark-soft-restaurant-dinner-rolls-recipe"}'::jsonb, false, null),
  (87, 'Pork and Fennel Sausage Rolls', 'pastry', 'medium', 30, 33, 20, null, null, array[]::text[], '[{"name":"olive oil","amount":7,"unit":"g"},{"name":"garlic cloves, minced","amount":2,"unit":"count"},{"name":"small onion, finely chopped","amount":1,"unit":"count"},{"name":"celery stalk, finely chopped","amount":1,"unit":"count"},{"name":"streaky bacon, finely chopped","amount":150,"unit":"g"},{"name":"fennel seeds, toasted (optional)","amount":4,"unit":"g"},{"name":"ground pork","amount":500,"unit":"g"},{"name":"panko breadcrumbs","amount":40,"unit":"g"},{"name":"egg","amount":1,"unit":"count"},{"name":"salt","amount":3,"unit":"g"},{"name":"black pepper","amount":1,"unit":"g"},{"name":"puff pastry sheets (25 cm square), thawed","amount":2.5,"unit":"count"},{"name":"egg, beaten, for glazing","amount":1,"unit":"count"}]'::jsonb, array['Heat the oil in a pan over medium-high heat and cook the garlic, onion and celery for 2 minutes. Add the bacon and cook 2 minutes more without browning it. Tip into a bowl and cool 10 minutes.', 'Add the fennel seeds, pork, breadcrumbs, egg, salt and pepper to the bowl and mix well with your hands.', 'Cut each pastry sheet in half to make five rectangles of about 25 x 12.5 cm.', 'Lay one rectangle with a long side facing you. Shape a fifth of the filling into a tight log along the middle, brush one long edge of the pastry with beaten egg, roll up and finish seam side down. Repeat with the rest.', 'Chill the logs for 1 hour if you have time. They cut more cleanly when cold.', 'Heat the oven to 180°C and line two trays with parchment. Cut each log into four, set the pieces on the trays and brush with beaten egg.', 'Bake 30 to 35 minutes, swapping the trays after 20 minutes, until the pastry is deep golden. The filling stays slightly pink because of the bacon. Serve warm.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/special-pork-fennel-sausage-rolls/"}'::jsonb, false, null),
  (88, 'Caramel Slice', 'bars', 'medium', 20, 27, 16, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"light brown sugar","amount":80,"unit":"g"},{"name":"unsweetened desiccated coconut","amount":45,"unit":"g"},{"name":"butter, melted","amount":125,"unit":"g"},{"name":"butter, for the caramel","amount":125,"unit":"g"},{"name":"light brown sugar, for the caramel","amount":80,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"sweetened condensed milk","amount":395,"unit":"g"},{"name":"dark chocolate","amount":200,"unit":"g"},{"name":"vegetable oil","amount":13,"unit":"g"}]'::jsonb, array['Heat the oven to 180°C. Grease a 28 x 18 cm tin and line it with parchment that hangs over the sides.', 'Mix the flour, 80 g of brown sugar, coconut and melted butter, press into the tin and bake 15 minutes until golden.', 'Lower the oven to 160°C.', 'Melt the caramel butter with its brown sugar and the vanilla in a saucepan over medium-low heat, whisking, until it starts to simmer.', 'Add the condensed milk and whisk constantly for about 6 minutes, until large slow bubbles break on the base of the pan. Pour over the base and tilt the tin to level it.', 'Bake 12 minutes (brown patches are normal). Cool 20 minutes on the counter, then 30 minutes in the fridge.', 'Melt the chocolate with the oil in the microwave in 30-second bursts, stirring between each. Pour over the caramel and shake the tin gently to level it.', 'Chill about 1 hour until set. Stand 5 minutes at room temperature before cutting, so the chocolate does not crack.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/caramel-slice/"}'::jsonb, false, null),
  (89, 'Plain Scones', 'scones', 'easy', 10, 12, 10, null, null, array['vegetarian']::text[], '[{"name":"self-raising flour","amount":450,"unit":"g"},{"name":"cold salted butter, cubed","amount":80,"unit":"g"},{"name":"cold milk","amount":255,"unit":"g"},{"name":"strawberry jam, to serve","amount":160,"unit":"g"},{"name":"heavy cream, whipped, to serve","amount":250,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C.', 'Put the flour in a food processor, add the cold butter and blitz for about 8 seconds, until it looks like breadcrumbs.', 'Pour the milk evenly over the top and blitz 6 to 8 seconds more, until the crumbs gather into a ball or two.', 'Turn out onto a lightly floured surface and knead no more than 10 times, just to make a smooth ball. Pat into a disc about 2 cm thick.', 'Flour a 5 cm round cutter and cut straight down without twisting. Move the scones to a tray without squeezing the cut sides. Gather the scraps, pat out and cut again to make 10.', 'Brush the tops with a little milk if you like. Bake 10 to 12 minutes, until golden and hollow-sounding when tapped.', 'Wrap loosely in a tea towel to soften the tops and serve warm with the jam and whipped cream.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/plain-scones/"}'::jsonb, false, null),
  (90, 'Brioche Buns', 'buns', 'hard', 15, 16, 6, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":330,"unit":"g"},{"name":"dry milk powder","amount":28,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"water","amount":57,"unit":"g"},{"name":"butter, cool","amount":142,"unit":"g"},{"name":"egg white, for the wash","amount":1,"unit":"count"},{"name":"water, for the wash","amount":15,"unit":"g"}]'::jsonb, array['Mix and knead in a mixer or bread machine for 15 to 20 minutes until smooth and shiny. It starts sticky, so do not hand-knead.', 'Shape into a ball, put in a greased bowl, cover and rise 1 hour.', 'Refrigerate overnight to slow the rise and firm the dough.', 'Divide into 6 pieces, flatten each into a ball and set on a lined tray with 6 to 8 cm between them.', 'Cover and rise 1 to 3 hours until quite puffy. Heat the oven to 190°C near the end.', 'Brush with the egg white beaten with water, add seeds if you like, and bake 14 to 18 minutes, tenting with foil after 10, until at least 88°C inside.', 'Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/brioche-buns-recipe"}'::jsonb, false, null),
  (91, 'Quebec Sugar Pie', 'pie', 'medium', 20, 38, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"light brown sugar","amount":210,"unit":"g"},{"name":"all-purpose flour","amount":40,"unit":"g"},{"name":"cornstarch","amount":14,"unit":"g"},{"name":"salt","amount":0.5,"unit":"g"},{"name":"heavy cream","amount":375,"unit":"g"},{"name":"maple syrup","amount":165,"unit":"g"},{"name":"double 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"milk, for brushing","amount":15,"unit":"g"}]'::jsonb, array['Off the heat, whisk the brown sugar, flour, cornstarch and salt in a pot.', 'Whisk in the cream and maple syrup until smooth.', 'Bring to the boil, whisking all the time, then take off the heat and let it cool.', 'Heat the oven to 200°C with a rack in the lowest position.', 'Line a 23 cm pie dish with half the crust and pour in the cooled filling.', 'Brush the rim with milk. Cut the rest of the crust into strips about 2.5 cm wide, brush them with milk and weave a lattice over the filling. Press the edges to seal and trim off the extra.', 'Bake 35 to 40 minutes, until the crust is golden and the filling is bubbling.', 'Cool about 3 hours so the filling sets. Serve warm or cold.']::text[], '{"name":"Ricardo","url":"https://www.ricardocuisine.com/en/recipes/5386-sugar-pie"}'::jsonb, false, null),
  (92, 'Pecan Pie Bars', 'bars', 'medium', 25, 37, 16, 'square-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":100,"unit":"g"},{"name":"cornstarch","amount":30,"unit":"g"},{"name":"icing sugar","amount":60,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"cold butter, cubed","amount":113,"unit":"g"},{"name":"butter, for the filling","amount":170,"unit":"g"},{"name":"light brown sugar","amount":160,"unit":"g"},{"name":"honey","amount":63,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"salt, for the filling","amount":0.5,"unit":"g"},{"name":"heavy cream","amount":30,"unit":"g"},{"name":"pecans, coarsely chopped","amount":340,"unit":"g"}]'::jsonb, array['Line a 23 cm square tin with foil, leaving it hanging over two sides, and grease it.', 'Pulse the flour, cornstarch, icing sugar and salt in a food processor. Add the cold butter and pulse until it looks like coarse meal with pea-sized lumps. It will seem dry.', 'Press firmly into the tin in an even layer and chill 15 minutes while the oven heats to 175°C.', 'Bake the crust about 17 minutes, until set but not browned. Leave the oven on.', 'Stir the filling butter, brown sugar, honey, vanilla and salt in a saucepan over medium-low heat until the sugar dissolves. Turn up the heat and boil gently for 3 minutes.', 'Stir in the cream and the pecans, then pour over the crust (it can still be warm).', 'Bake about 20 minutes, until bubbling and caramel coloured. Cool completely, lift out by the foil and cut into 5 cm squares.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/pecan-squares.html"}'::jsonb, false, null),
  (93, 'No-Bake Chocolate Cheesecake Bars', 'bars', 'easy', 20, 0, 16, 'square-20', null, array['vegetarian']::text[], '[{"name":"chocolate sandwich cookies","amount":227,"unit":"g"},{"name":"salt","amount":0.5,"unit":"g"},{"name":"butter, melted","amount":43,"unit":"g"},{"name":"cream cheese","amount":453,"unit":"g"},{"name":"icing sugar","amount":86,"unit":"g"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"salt, for the filling","amount":0.5,"unit":"g"},{"name":"semisweet chocolate","amount":114,"unit":"g"},{"name":"espresso powder","amount":0.5,"unit":"g"},{"name":"heavy cream","amount":114,"unit":"g"}]'::jsonb, array['Pulse the cookies and salt to fine crumbs. Add the melted butter until the mix holds together when squeezed.', 'Press into a lined, greased 20 cm square tin and freeze at least 1 hour.', 'Beat the cream cheese, icing sugar, vanilla and salt until smooth.', 'Spread about 180 g of the filling over the crust and put the rest in a large bowl.', 'Melt the chocolate with the espresso powder in short microwave bursts, stirring between each, then stir it into the reserved filling.', 'Whip the cream to medium peaks and fold it into the chocolate filling.', 'Spread over the base and chill at least 8 hours. Slice with a hot, dry knife.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/no-bake-chocolate-cheesecake-bars-recipe"}'::jsonb, false, null),
  (94, 'Spiced Apple Muffins', 'muffins', 'easy', 15, 27, 12, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":100,"unit":"g"},{"name":"dark brown sugar","amount":55,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"plain yogurt","amount":240,"unit":"g"},{"name":"whole wheat flour","amount":120,"unit":"g"},{"name":"all-purpose flour","amount":130,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":8,"unit":"g"},{"name":"ground nutmeg","amount":1,"unit":"g"},{"name":"ground cloves","amount":0.5,"unit":"g"},{"name":"baking apples, peeled and finely chopped","amount":250,"unit":"g"},{"name":"dark brown sugar, for the top","amount":80,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and grease a 12-cup muffin tin.', 'Beat the soft butter with the sugar and the 55 g of brown sugar for 1 to 2 minutes until fluffy.', 'Beat in the egg, then the yogurt. The batter looks curdled at this point, which is fine.', 'Add both flours, the baking powder, baking soda, salt and spices and mix on low until just combined. The batter is very thick.', 'Fold in the chopped apples without overmixing.', 'Fill the cups full and sprinkle the remaining brown sugar over the tops.', 'Bake 25 to 30 minutes, until a skewer comes out clean. Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"Once Upon a Chef","url":"https://www.onceuponachef.com/recipes/apple-spice-muffins.html"}'::jsonb, false, null),
  (95, 'Banana Chocolate Chip Muffins', 'muffins', 'easy', 10, 27, 12, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":135,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"very ripe bananas, mashed","amount":3,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":190,"unit":"g"},{"name":"baking soda","amount":6,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"semisweet chocolate chips","amount":170,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line a 12-cup muffin tin with paper cases.', 'Beat the soft butter with the sugar, then beat in the lightly beaten eggs.', 'Mix in the mashed bananas and vanilla.', 'Whisk the flour, baking soda and salt in another bowl and mix into the wet ingredients until just combined.', 'Fold in three-quarters of the chocolate chips. Divide the batter between the cases and scatter the rest of the chips on top.', 'Bake 25 to 30 minutes, until golden and a skewer comes out clean. Start checking at 25 minutes.', 'Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"Natasha''s Kitchen","url":"https://natashaskitchen.com/banana-muffins-recipe/"}'::jsonb, false, null),
  (96, 'Zucchini Chocolate Chip Muffins', 'muffins', 'easy', 10, 24, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":190,"unit":"g"},{"name":"baking powder","amount":2,"unit":"g"},{"name":"baking soda","amount":3,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vegetable oil","amount":100,"unit":"g"},{"name":"sugar","amount":150,"unit":"g"},{"name":"milk","amount":30,"unit":"g"},{"name":"vanilla extract","amount":6,"unit":"g"},{"name":"zucchini, grated","amount":225,"unit":"g"},{"name":"semisweet chocolate chips","amount":85,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line or grease a 12-cup muffin tin.', 'Whisk the flour, baking powder, baking soda, salt and cinnamon.', 'In another bowl whisk the egg, oil, sugar, milk and vanilla.', 'Add the dry ingredients to the wet and whisk until smooth.', 'Grate the zucchini on the large holes of a grater and fold it in, followed by about two-thirds of the chocolate chips.', 'Divide between the cups and sprinkle the remaining chips on top.', 'Bake 22 to 25 minutes, until a skewer comes out clean. Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"Natasha''s Kitchen","url":"https://natashaskitchen.com/zucchini-muffins-recipe/"}'::jsonb, false, null),
  (97, 'Soft No-Yeast Flatbread', 'flatbread', 'easy', 15, 10, 6, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":50,"unit":"g"},{"name":"milk","amount":190,"unit":"g"},{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"salt","amount":3,"unit":"g"}]'::jsonb, array['Warm the butter and milk together until the butter has just melted.', 'Mix the flour, salt and the warm milk mixture in a bowl until a dough forms.', 'Knead on a floured surface for about 2 minutes until smooth, adding a little more flour if it sticks.', 'Wrap the dough and rest it at room temperature for 30 minutes.', 'Cut into 6 pieces, roll each into a ball, then roll out to a 20 cm round about 2 to 3 mm thick.', 'Heat a dry non-stick pan over high heat. Cook one flatbread for 1 to 1.5 minutes until it puffs and the underside has golden patches, then flip and cook 45 to 60 seconds more.', 'Stack the cooked flatbreads in a clean tea towel to keep them warm and soft while you cook the rest.']::text[], '{"name":"RecipeTin Eats","url":"https://www.recipetineats.com/easy-soft-flatbread-yeast/"}'::jsonb, false, null),
  (98, 'Hot Cross Muffins', 'muffins', 'easy', 30, 20, 12, null, null, array['vegetarian']::text[], '[{"name":"golden raisins","amount":149,"unit":"g"},{"name":"rum or water","amount":28,"unit":"g"},{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"sugar","amount":66,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":1,"unit":"g"},{"name":"ground nutmeg","amount":1.5,"unit":"g"},{"name":"ground allspice","amount":0.5,"unit":"g"},{"name":"milk","amount":340,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"butter, melted","amount":113,"unit":"g"},{"name":"candied mixed peel or extra dried fruit","amount":85,"unit":"g"},{"name":"icing sugar","amount":142,"unit":"g"},{"name":"butter, softened","amount":28,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"milk or cream, for the icing","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and prepare a 12-cup muffin tin.', 'Soak the raisins in the warmed rum or water while you prepare the rest.', 'Whisk the flour, baking powder, sugar, salt and spices.', 'Beat the milk and eggs, stir in the melted butter, then add to the dry mix with the fruit and peel and stir until just combined.', 'Scoop a generous 60 ml into each cup and bake 20 to 25 minutes until a skewer comes out clean. Cool on a rack.', 'Beat the icing sugar, soft butter, vanilla and milk until smooth, adding liquid until pipeable.', 'Pipe a cross on each cooled muffin.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/hot-cross-muffins-recipe"}'::jsonb, false, null)
